/* Editorial interpretations; new generated paintings, not historic painter originals. */
window.ClassicaImpressiveCatalog={"version":"20261025-impressionists-v1","artists":{"morisot":{"name":"Berthe Morisot","ja":"ベルト・モリゾ","style":"Morisot at her most radical: airy, rapid diagonal bristle marks; dry, sketch-like touches over visibly exposed warm-white ground; fleeting grey-green, silver, mauve and touches of black; forms found and lost through white space. Unfinished passages and gestural drawing carry intimacy. Avoid a uniformly detailed, smoothly finished oil surface.","source":"https://www.marmottan.fr/en/collections/berthe-morisot/"},"monet":{"name":"Claude Monet","ja":"クロード・モネ","style":"Monet: color and light dissolve contours into broad patches of broken paint; horizontal touches on water, fused and scumbled atmosphere above; blues, greens and complementary violet/gold reflections chosen for this particular time of day. Emphasize optical color relationships over drawn outlines. Not Renoir-like pretty people or a small decorative stipple filter.","source":"https://www.metmuseum.org/ja/essays/impressionism-art-and-modernity"},"pissarro":{"name":"Camille Pissarro","ja":"カミーユ・ピサロ","style":"Pissarro rural Impressionism: carefully constructed spatial planes made from many small, DENSE comma-shaped touches, earth ochre and warm grey against complex muted greens. Solid working countryside and ordinary life; visual order and patient material observation, not vaporous white Monet fog and not Renoir pink softness.","source":"https://www.metmuseum.org/ja/essays/impressionism-art-and-modernity"},"sisley":{"name":"Alfred Sisley","ja":"アルフレッド・シスレー","style":"Sisley: a large airy sky, lucid river space and a low believable horizon; fresh feathery strokes of blue, white and varied green, deft horizontal reflections, sturdy but unobtrusive perspective. Open breathing space and changing weather; no thick orange-violet impasto, no ornamental portrait softness.","source":"https://onlinecollection.nationalgallery.ie/objects/11782/the-banks-of-the-canal-du-loing-at-saintmammes"},"renoir":{"name":"Pierre-Auguste Renoir","ja":"ピエール＝オーギュスト・ルノワール","style":"Renoir of the 1870s: supple round modeling of real human forms, warm living flesh and rosy gold dappled light, deep blue-violet shadows and juicy rounded brush touches. Warm sociability, bodies and cloth with convincing weight; soft interpenetrating color rather than sharp outlines. No identical scratchy white landscape texture over everything.","source":"https://www.nationalgallery.org.uk/paintings/learn-about-art/guide-to-impressionism"},"degas":{"name":"Edgar Degas","ja":"エドガー・ドガ","style":"Degas PASTEL and gouache on coarse colored paper, not a generic oil painting. Angular charcoal construction, directional hatching, dry powdery pigment, abrupt cropped diagonals, strong figure silhouettes. Ochre, acidic green, rust, blue and cream over exposed umber paper. Observational anatomy and theatrical light; unfinished passages contrast with sharp drawn edges.","source":"https://www.nationalgallery.org.uk/paintings/hilaire-germain-edgar-degas-ballet-dancers"},"cassatt":{"name":"Mary Cassatt","ja":"メアリー・カサット","style":"Cassatt mature Impressionist figure painting shaped by Japanese prints: boldly flattened MATTE areas, firm selective dark contours, high viewpoints and interlocking shapes. Coral textile patterns, sage green, cream and selective ultramarine. Precise, unsentimental intimacy and convincing real anatomy. Do not turn this into a hazy Monet landscape or glossy sentimental illustration.","source":"https://www.metmuseum.org/ja/perspectives/mary-cassatt-modernist-mother-child"},"caillebotte":{"name":"Gustave Caillebotte","ja":"ギュスターヴ・カイユボット","style":"Caillebotte 1870s urban Impressionism: exacting architectural perspective, firm clean edges, broad relatively SMOOTH tonal modeling and materially observed objects, photographic spatial cropping. Slate grey, bottle green, black-blue and limited warm ochre. Controlled reflected light. Avoid fluffy broken white-and-pink texture; this artist belongs to the group but does not paint like Monet.","source":"https://www.nga.gov/exhibitions/gustave-caillebotte-painters-eye"},"guillaumin":{"name":"Armand Guillaumin","ja":"アルマン・ギヨマン","style":"Guillaumin: saturated Impressionist landscape built from thick loaded blunt IMPASTO strokes and rugged interlocking patches. Cobalt and violet against burning copper-orange and acidic yellow-green. Strong dark masses, directional force and palpable paint, with believable landscape structure. Not delicate pastel prettiness, not a smooth digital neon painting.","source":"https://art.seattleartmuseum.org/objects/12687/essence-of-spring-chevreuse-valley"},"twachtman":{"name":"John Henry Twachtman","ja":"ジョン・ヘンリー・トワクトマン","style":"Twachtman American Impressionism: restrained near-MONOCHROME silver-grey, pale jade, cold ivory and the faintest rose; thin scumbled veils on matte canvas, simplified planes, broken soft edges and a few spare dark linear accents. Intimate quiet landscape, still air and tonal harmony; not highly saturated French plein-air impasto or decorative pink clouds.","source":"https://americanart.si.edu/artist/john-henry-twachtman-4901"},"hassam":{"name":"Childe Hassam","ja":"チャイルド・ハッサム","style":"Hassam American Impressionism: crisp small broken strokes and flickering urban sunlight, strong vertical rhythm, bright cobalt, chrome yellow, white and sparse vermilion. Lively flags, stone and crowds with clear structural rhythm. Sparkling emphatic civic daylight, not a hazy rural Monet scene.","source":"https://www.metmuseum.org/ja/essays/childe-hassam-1859-1935"}},"works":[{"id":"fur-elise","title":"エリーゼのために","artist":"morisot","subject":"An unsealed blank ivory letter beside a closed rosewood piano and an empty chair, a gauzy garden-window curtain above. The letter and the window light form one intimate vertically arranged subject.","rationale":"献辞の相手が定まらない私的な呼びかけと、半音の揺れを伴って回帰するロンドから、手紙と誰もいない室内を選んだ。モリゾの親密な空間と白地を生かす筆触で、特定の恋人の史実としては描かない。","source":"songs/fur-elise.md","evidence":{"summary":"約3分のロンド形式の小品。冒頭の半音の揺れが、一度聴けば忘れられない主題を作っている。","nameOrigin":"ノールが伝えた自筆譜の献辞「Für Elise（エリーゼのために）」による。ただし原本は現存せず、Therese→Eliseの書き間違い説や、献辞を後の所有者が書き加えたとする説もある。","features":"ABACA型の5部ロンド、イ短調、3/8拍子。冒頭の半音揺れ（E-D#）の音形で曲が識別でき、8小節ずつの対称構造は反復にも向く。B・C両エピソードの旋律も冒頭の音高輪郭（上方隣接音から下降音階）を使い、全体に統一感がある。トリル、分散和音、オクターブ、トレモロ、連打音、3度・6度の重音、半音階など技法は多彩で、小品ながら練習曲的でもある。版により7小節目の2つめの音がEかDかが異なる（ノール版はE、草稿に近い読みはD）。","structure":[["A（Poco moto、イ短調、3/8）","EとD#が揺れ動く有名な主題。アルペッジョの伴奏とともに、問いと答えの形の8小節を作る。9小節目から平行調をかすめ、属音Eを引き延ばして主題に戻る。"],["B（23小節〜、ヘ長調）","下属調側のヘ長調で始まり、主題の音形を少し装飾して示す。属調ハ長調へ転じ、32分音符の走句で終止を繰り返す。"],["A（再現）","冒頭部がそのまま戻る。"],["C（59小節〜、主調）","主音の保続低音の上で、和音を激しく連打する。ナポリ和音をかすめ、76小節で完全に静止する。"],["A（最終）と結び","イ短調の上行アルペッジョと2オクターブの半音階下降を経て、A部が最後に回帰し、後奏なしで終わる。"]]},"asset":"assets/impressive/fur-elise.webp","focus":[0.5,0.48],"motion":"light","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"moonlight","title":"ピアノソナタ第14番「月光」第1楽章","artist":"monet","subject":"A small veiled moon above a hushed blue-violet lake; three near-parallel bands of very small silver reflections, low dark shore. Broad quiet water and a very distant almost invisible boat.","rationale":"第1楽章の途切れない三連符と低く持続する旋律を、三層の小さな反射と暗い水平面へ置き換える。月光という後世の比喩を、モネの輪郭を溶かす色の関係で扱う。","source":"songs/moonlight.md","evidence":{"summary":"途切れない三連符の伴奏の上で、低い旋律がゆっくり語られる緩徐楽章。ソナタの一般的な配置を逆にし、緩い楽章から始まる。","nameOrigin":"ベートーヴェン自身の命名ではない。詩人ルートヴィヒ・レルシュタープが、第1楽章の効果を「月明かりに揺れる湖」のような情景にたとえたことに由来する（命名時期は英語版が1824年、日本語版が1832年で食い違う）。「ルツェルン湖の舟」という有名な表現は、1852年にヴィルヘルム・フォン・レンツが付け加えたものらしい。チェルニーは先んじて「夜景。遠くから悲しげな亡霊の声が聞こえる」と評した。ベートーヴェンはこの人気を快く思っていなかったとされる。","features":"嬰ハ短調、2/2拍子。右手の三連符が最後まで途切れず、この音型が全体のトーンを決める。旋律は主に低音側で語られ、右手は同じ音型を保つ。音量はpp〜pの範囲にとどまる。弱音と持続音を重ねたペダルの響きが主役で、旋律の動きは小さい。この三連符の音型は終楽章のアルペッジョの動機へ発展し、全曲の統一にも関わる。","structure":[["冒頭指示（Adagio sostenuto）","「全曲を極めて繊細に、ダンパーなしで演奏すること」という指示で始まる。現代ピアノではサステインペダルを使い続ける解釈になるが、響きが濁りやすい。形式の見方は、三部形式とする説や、変則的なソナタ形式とする説に分かれる。"],["序奏とA主題","低音のオクターブに続き、途切れない三連符の伴奏の上に付点リズムの旋律が置かれる。葬送を思わせる、とする見方もある。"],["B主題と中間部","ロ長調付近でB主題が出る。中間部ではA主題の素材から出発し、旋律的な要素が薄れ、三連符が高音域へ弧を描いて上り下りする。"],["再現","A主題が再び現れ、B主題も続いて再現される。"],["コーダ","約2オクターブにわたる三連符の往復の下で、低音がA主題のリズムを繰り返し、最弱音で終わる。アタッカの指示で休みなく第2楽章（Allegretto、変ニ長調）へ進む。"]]},"asset":"assets/impressive/moonlight.webp","focus":[0.5,0.48],"motion":"water","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"tristesse","title":"別れの曲（練習曲 Op.10-3）","artist":"pissarro","subject":"A country departure platform and an empty bench, a very distant departing carriage on an ochre lane; layered poplars and roofs after late-afternoon rain.","rationale":"右手の三層の書法と歌う主部、激しい中間部を、手前のベンチ・道・奥の町の層に重ねる。後世の別れの通称は、見送ったあとの空間として扱う。","source":"songs/tristesse.md","evidence":{"summary":"速さを競う練習曲とは正反対に、遅いテンポで旋律を歌わせる練習曲。右手が旋律・内声・伴奏の三層を受け持つ。","nameOrigin":"日本で定着した「別れの曲」という通称は、1934年のドイツ映画『Abschiedswalzer』（邦題『別れの曲』、ゲツァ・フォン・ボルヴァリー監督）の邦題に由来する。この映画はショパンの伝記映画で、本曲が主題曲に使われた。日本では1935年にキャストを替えたフランス語版（La chanson de l'adieu）が公開されて大ヒットし、これを機に本曲が「別れの曲」と呼ばれるようになった。海外の通称は「Tristesse（悲しみ）」で、フランス語圏では「L'intimité」、英語圏では「Farewell」とも呼ぶ。いずれもショパン自身が付けたものではない。","features":"三部形式（A-B-A'）で、夜想曲のような歌の曲想が指摘されることが多い。A部の伴奏は右手の細かい揺れと左手のシンコペーションが重なる。旋律には音の反復が多く、第4〜5小節の長3度の揺れはドビュッシー的な響きを先取りしているとカゼッラが述べている。B部は減7の和音と三全音を連ね、ホ長調を保ちつつ半音階的な色合いが強まる。ペダル指示は自筆譜にも原典版にも見当たらない。","structure":[["A部（冒頭〜約20小節、Lento ma non troppo）","右手の最上声が息の長い旋律を歌い、内声と細かい16分音符の揺れが同じ手で伴奏を務める。左手は和音とシンコペーションで支える。楽句の構成は(5+3)+(5+7)小節という非対称型。声部ごとに別々のクレッシェンド・ディミヌエンド記号が付くのも新しい点。"],["B部（poco più animato、約21〜61小節）","旋律と伴奏が重音の連なりに融合する中間部。8小節の楽句が5つ並び、第3楽句は減7と三全音の連続で転調が激しい。第4楽句（46〜53小節）は両手の6度重音によるクライマックス。第5楽句（54〜61小節）は属七の和音を引き延ばしてA部再現へつなぐ。"],["A'部と終結","A部が短縮して戻り、静かに閉じる。自筆譜末尾には第4番へのアタッカ指示がある。"]]},"asset":"assets/impressive/tristesse.webp","focus":[0.5,0.48],"motion":"foliage","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"fantaisie-impromptu","title":"幻想即興曲","artist":"guillaumin","subject":"Two fast crossing river currents between dark rocks, a luminous calm pool in the middle and storm-cleared distance; dense copper, violet and green strokes.","rationale":"右手の4と左手の3の交差を交わる水流に、中間部のカンタービレを光の残る静かな淵に結びつけた。ギヨマンの厚い強色の筆触で両者の力の差を描く。","source":"songs/fantaisie-impromptu.md","evidence":{"summary":"右手の16分音符と左手の三連符がぶつかる両端部と、中間部の甘い旋律の対比。ショパン自身は生前に出版しなかった。","nameOrigin":"「幻想即興曲」の題はショパンの生前にはなく、フォンタナが1855年に出版したときに付けた。即興曲としては最初に書かれたが出版が最後になったため、第4番という番号になった。この番号は旧全集の便宜上のもの。","features":"複合三部形式（A-B-A'）。2/2拍子の中で、右手の16分音符と左手の三連符が交差リズムを作り、緊迫感を支える。中間部は同主調の異名同音（変ニ長調）に移り、急から緩へ性格を一変させる。オスターの分析では、同じ嬰ハ短調の「月光」ソナタとの類縁が強い。主題提示の2小節後の急速なパッセージは、「月光」終楽章のカデンツァと同じ音を1オクターヴ上で用いる。一方、ハネカーは一部を「感傷的」で「気高さに欠ける」と批判している。","structure":[["A部（Allegro agitato、嬰ハ短調、2/2）","右手の16分音符と左手の三連符が絶えず絡み合い、休みなく動く。「月光」ソナタ第3楽章との類似がオスターのシェンカー分析で指摘されている。"],["B部（Largo → Moderato cantabile、変ニ長調）","嬰ハ長調と異名同音の変ニ長調に移り、のびやかな歌になる。この旋律は1917年のポピュラー曲『I'm Always Chasing Rainbows』に引用された。"],["A'部（Presto、嬰ハ短調へ復帰）","冒頭の急速な動きが戻る。"],["コーダ","左手がB部の主題を静かに弾き直し、右手は16分音符を続ける。最後は嬰ハ長調の和音（ピカルディ終止）で静かに閉じる。"]]},"asset":"assets/impressive/fantaisie-impromptu.webp","focus":[0.5,0.48],"motion":"water","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"nocturne-9-2","title":"ノクターン第2番","artist":"renoir","subject":"A quiet riverside terrace at early night, a small table with a glass, very modest flowers, fine lamplight scattered over the river and curving foliage.","rationale":"12/8の揺れと、同じ旋律が装飾を増して戻る構造から、灯火が水面で表情を変える夜のテラスを選んだ。ルノワールの暖色と柔らかな量感を用いる。","source":"songs/nocturne-9-2.md","evidence":{"summary":"揺れる左手の伴奏の上で、同じ旋律が回帰するたびに装飾を増していく夜想曲。ショパンの夜想曲の中でも特に広く親しまれている。","nameOrigin":"「ノクターン（夜想曲）」の語は、夜を指すラテン語Noxに由来し、修道院の晩祷や夜の黙想の意味合いから転じたと考えられている。ピアノ独奏曲のジャンルはジョン・フィールドが始めた。本曲に固有の愛称は確認できず、日本では「ショパンのノクターン」と言えばこの曲を指すことが多い。","features":"拍子は12/8で、左手は広い音域に配置した分散和音をダンパーペダルでつなぎ、旋律を支える響きの土台にしている。伴奏は12拍を3拍ずつ四つに分けるワルツ風の揺れを緩やかに強調する。右手の旋律は再現のたびにトリルや装飾音で飾られ、イタリア・オペラの装飾的歌唱を思わせる。構造は単純だが、変奏によって同じ旋律を繰り返しながら表情を変える点が特徴。一方で、旋律が装飾されて繰り返されるだけで内容は乏しいとする見方もある。","structure":[["A（主題提示）","Andante、変ホ長調、12/8。弱音でレガートに歌う旋律が、優美な上行の跳躍を伴って始まる。"],["A（反復）","主題が繰り返され、装飾音が加わる。"],["B（副次旋律）","副次的な旋律がルバートで奏される。"],["A（再現・装飾増）→ B（再現）","主題と副次旋律が再び現れ、そのたびに装飾が増える。"],["A＋コーダ","主題が最も装飾された形で戻り、コーダへ。終わり近くの小節にはsenza tempo（テンポなし）の指示があり、リズムの自由度が高い。全体はA-A-B-A-B-A-コーダ（ロンド風）と見る説と、英語版が示す拡張された二部形式（A,A,B,A,B,A＋コーダ）とする説がある。"]]},"asset":"assets/impressive/nocturne-9-2.webp","focus":[0.5,0.48],"motion":"water","medium":"painting","focusPortrait":[0.41,0.48]},{"id":"raindrop","title":"前奏曲 第15番「雨だれ」","artist":"caillebotte","subject":"A deserted Mediterranean cloister courtyard in the rain, seen from an arcade; one roof drip reaches a small central puddle, pale wet paving divided from deep slate shadow.","rationale":"持続する変イ音／嬰ト音と長短調の対比を、同じ滴が明るい石畳と暗い回廊をつなぐ情景へ読む。カイユボットの厳密な遠近法と抑えた濡れた灰色で構成する。","source":"songs/raindrop.md","evidence":{"summary":"曲全体で鳴り続ける同じ音が、雨だれを思わせる。穏やかな主題と、暗く迫る中間部の対比。24曲の前奏曲で最長。","nameOrigin":"「雨だれ」はショパン自身の命名ではない。命名者と時期は確認できなかった。【史実】1838〜39年の冬にショパンとサンドがマジョルカ島に滞在したこと。作品28の完成が1839年1月のマジョルカであること。サンドが回想録で、雨の夜にショパンが水滴の夢を見て、雨音の模倣だとする解釈に抗議したと書いていること。【伝承・推測】この逸話に出てくる曲を、サンドは曲名で特定していない。多くの評論家が、繰り返される変イ音（嬰ト音）の響きから第15番だと推測してきたにすぎない。ピーター・ダヤンは、サンドもショパンの抗議を受け入れ、この曲を雨音の模倣ではなく自然の響きの音楽的な翻訳と見ていたと指摘している。","features":"曲全体の核は、右手内側または低音域で刻まれ続ける変イ音（中間部では異名同音の嬰ト音）。変ニ長調の明るさと嬰ハ短調の暗さが異名同音を介して対比され、同じ反復音が文脈によって意味を変える。24曲中で最も長く、演奏時間は約5〜7分。中間部では属音の持続音が低音に固定され、音が積み重なって緊迫感を強める。長調から短調への移行は、両調が異名同音で結ばれていることを活かした大胆な場面転換である。","structure":[["A（変ニ長調、Sostenuto、4/4）","穏やかで晴朗な主題。変イ音の連打が曲全体を通して鳴り続け、雨だれに聴こえる要因となる。"],["B（嬰ハ短調）","異名同音で嬰ハ短調に移り、陰鬱で重い中間部へ。属音のペダルが途切れず低音で続く（バッソ・オスティナート）。変イ音は嬰ト音として、より執拗になる。"],["A'（変ニ長調への回帰）","冒頭の主題に戻る。ニークスは、中間部の悪夢から覚めた後の清明な自然のようだと評した。"]]},"asset":"assets/impressive/raindrop.webp","focus":[0.5,0.48],"motion":"rain","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"clair-de-lune","title":"月の光（ベルガマスク組曲 第3曲）","artist":"monet","subject":"An overgrown garden walk at moonrise beside still water, a curved path and tiny almost dissolved distant masked revellers under trees; pearl green and lavender.","rationale":"ヴェルレーヌの詩と旧題の感傷的な散歩、弱音から流動する中間部への変化を夜の庭へ結びつけた。モネの光の色面で、仮面の人物より月明かりと水面を主役にする。","source":"songs/clair-de-lune.md","evidence":{"summary":"弱音の和音と流れるアルペッジョで、月明かりの情景を描いた小品。ヴェルレーヌの詩に結びつく題名を持つ。","nameOrigin":"題名はヴェルレーヌ『艶なる宴』所収の詩「Clair de lune（月の光）」から。この曲の旧題は「感傷的な散歩（Promenade sentimentale）」で、これもヴェルレーヌの詩の題。組曲名「ベルガマスク」は同詩第1節の「masques et bergamasques」に由来する。","features":"変ニ長調、9/8拍子の複合3拍子で、全体の大半が弱音で奏される。和声は古典的な機能和声の連なりから距離を取り、旋法的で曖昧な響きを生む。前奏曲の部分には、同じヴェルレーヌ詩にフォーレが付けた歌曲の伴奏に似た音形が出るとの指摘もあり、先行作曲家の影響が見える初期作でもある。ピアノ書法は、内省と距離感の間を行き来する印象主義的な響きの扱いが核になる（細かな和声分析は、参照した解説では詳述されていない）。","structure":[["冒頭主題（A）","変ニ長調・9/8拍子、Andante très expressif。弱音で、柔らかい下降する旋律をゆるやかな和音で支える。調性感は穏やかにぼかされる。"],["中間部（B）","律動が流れ出し、アルペッジョ状の伴奏の上で旋律が次第に高まる。曲中で最も感情の振れ幅が大きい部分。"],["主題の再現（A'）と結び","冒頭の主題が戻り、音量を落として静かに閉じる。全体は緩-やや動く-緩の三部形式的な構成（小節番号までは未確認）。"]]},"asset":"assets/impressive/clair-de-lune.webp","focus":[0.5,0.48],"motion":"water","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"gymnopedie-1","title":"ジムノペディ 第1番","artist":"degas","subject":"An almost empty rehearsal room with one modestly dressed adult dancer resting by a barre, a small distant figure beyond a doorway; two broad alternating light planes and diagonal floorboards.","rationale":"二つの和音の往復と装飾を排した旋律、古代の舞踏に由来する題名から、踊りの前後の静止を選んだ。ドガの素描と粗い色紙の余白で時間の疎らさを描く。","source":"songs/gymnopedie-1.md","evidence":{"summary":"左手の2つの和音の往復の上に、装飾を排した旋律が静かに乗る。速度表示は「ゆっくりと、苦しみをもって」。","nameOrigin":"古代スパルタの祭り「ギュムノパイディア」のフランス語形。gymnos（裸の・武器を持たない）が語源に含まれる。サティは『サランボー』から取ったと述べたが、詩人コンタミーヌ・ド・ラトゥールの詩に同じ語が出る点や、辞典の定義から得たとの説もある。ピュヴィ・ド・シャヴァンヌの絵の影響を推す見方もある。","features":"3/4拍子の遅いテンポと、左手の「低音→和音」の反復が骨格をなす。冒頭は下属音上のGmaj7と主音上のDmaj7の交替で、長調とも短調ともつかない曖昧な色合いを出す。旋律は和声に対して穏やかな不協和を保ち、哀愁を生む。装飾を排した簡素な書法は、サティのいう「新しい単純さ」の最初の例とヘンレ版は解説している。後に環境音楽の先駆とも見なされる。","structure":[["導入","3/4拍子、Lent et douloureux。左手の低音と和音の反復で、Gmaj7とDmaj7の2つの和音が交互に現れる。"],["主題部","その上に、装飾を排した静かな旋律が乗る。旋律は伴奏と軽い不協和を作る。"],["反復と変化、結び","主題が繰り返され、和声が少しずつ動いたのち、静かに終わる（確かめられたのは和声進行と速度表示まで。小節数や各部の長さは未確認）。"]]},"asset":"assets/impressive/gymnopedie-1.webp","focus":[0.5,0.48],"motion":"light","medium":"pastel","focusPortrait":[0.5,0.48]},{"id":"traumerei","title":"トロイメライ（子供の情景 第7曲）","artist":"cassatt","subject":"A clothed child daydreaming beside a window, seen from a high intimate angle; a folded book, patterned chair and garden light, no sentimental smiling pose.","rationale":"子供の情景の夢想と、同じ旋律が和声を変えて八度現れることから、日常の一瞬を内側から見つめる構図にした。カサットの観察的な人物造形と色面で記憶の親密さを出す。","source":"songs/traumerei.md","evidence":{"summary":"「夢想」を意味する題名どおり、ゆるやかに上り下りする4小節の旋律が、和声を変えながら8回現れる短い曲。","nameOrigin":"Träumereiはドイツ語で「夢想・白日夢」。曲集の各題は作曲後に付けられたもので、シューマンは「演奏と解釈への繊細なヒントにすぎない」と述べた。原題は『Leichte Stücke（やさしい小品）』、さらに『Kindergeschichten（子供の物語）』という案もあった。","features":"旋律は4度跳躍（ハ音からヘ音）で始まり、同じ4小節の旋律が繰り返されるたびに和声が塗り替えられる。中声部で複雑な和声進行を作り、幻想的な響きを得るのはシューマンの常套手段で、本曲が最も効果をあげた例とされる。拍頭の強調を避けて拍節を曖昧にし、夢のような質感を出している。第8曲「暖炉のそばで」も同じ4度跳躍で始まり、動機の共通性が指摘される。","structure":[["全体の枠組み","ヘ長調、4/4拍子、約2分半。『子供の情景』第7曲で、前曲の活気から一転して静かな夢想的世界に入る。"],["主要素材","4小節の旋律が上昇・下降を描き、それが8回現れるが、そのたびに和声づけが変わる。中声部の動きが幻想的な響きを作る。"],["拍節感","1拍目に強いアクセントを置かず、4拍子の拍節を意図的にぼかして浮遊感を出している。"],["小節ごとの形式区分","A-B-A'といった区分は、参照した出典では確認できなかった（未確認）。"]]},"asset":"assets/impressive/traumerei.webp","focus":[0.5,0.48],"motion":"light","medium":"painting","focusPortrait":[0.68,0.48]},{"id":"liebestraum-3","title":"愛の夢 第3番","artist":"renoir","subject":"An older couple sitting together on a shaded terrace, their hands close on a table, late rose-gold light among deep blue garden shadows.","rationale":"愛しうる限り愛せという原詩と、同じ旋律が高まりを経て戻ることから、成熟した二人の時間を選んだ。ルノワールの生きた肌と布の量感で愛情を描く。","source":"songs/liebestraum-3.md","evidence":{"summary":"歌曲を原曲とする、豊かな旋律と広い音域の伴奏の組み合わせ。2つのカデンツァが3つの部分を分ける。","nameOrigin":"Liebesträumeはドイツ語で「愛の夢」（複数形）。リスト自身は各曲を「Notturno（夜想曲）」と呼んだ。3曲は愛の3つの形（高貴な愛、官能的な愛、無条件の成熟した愛）を描く。第3番の原詩の題『O lieb, so lang du lieben kannst』は「愛しうる限り愛せ」の意。","features":"変イ長調、4つのフラット。1つの旋律が全曲を通して変奏されながら現れる。旋律は長音で保持され、逆向きの符尾の分散和音が周囲を流れるため、旋律を浮かび上がらせることが要となる。2つのカデンツァが3つの部分を分け、ロ長調やハ長調など遠隔調への転調が緊張を生む。第1番と同じ調で、第2番（ホ長調）は変イ長調と増5度の関係にあり、3曲組全体の対比が際立つ。","structure":[["第1部（A-A'-B）","変イ長調で、長く保たれる旋律の周りを分散和音が囲む。単純な主旋律が6小節で提示され、2回目は動きが増す。続く部分はpoco crescendo ed agitatoで緊張を高める。"],["第1カデンツァ","上行して下行する速い走句で、夢への移行を表すと解説される。"],["第2部（クライマックス）","主旋律がロ長調に現れ、次いでハ長調へと進み、最後に変イ長調へ戻る。右手のオクターヴと分散和音で頂点に達する。"],["第2カデンツァ","鍵盤の高音域から下降して緊張が解け、夢から現実へ戻る場面とされる。"],["終結部（再現とコーダ）","変イ長調で主旋律が回帰。dolceで、哀愁を帯びて静かに消えてゆく。演奏時間は約4分50秒。"]]},"asset":"assets/impressive/liebestraum-3.webp","focus":[0.5,0.48],"motion":"foliage","medium":"painting","focusPortrait":[0.41,0.48],"protect":[0.3,0.17,0.4,0.66]},{"id":"flaxen-hair","title":"亜麻色の髪の乙女（前奏曲集第1巻 第8曲）","artist":"morisot","subject":"A young adult woman with loose flaxen hair in a plain cream dress at the edge of a Scottish-like meadow; head, hands and a few grasses form a narrow central vertical subject, open pale sky.","rationale":"ルコント・ド・リールの金髪の娘を置く牧歌と、五音音階の素朴さに基づく。モリゾの素早い白と緑の筆触で、髪と草が空気に溶ける軽さを描く。","source":"songs/flaxen-hair.md","evidence":{"summary":"素朴な旋律と淡い響きで、詩の中の金髪の娘を描いた前奏曲集屈指の小品。","nameOrigin":"ルコント・ド・リールの詩「La fille aux cheveux de lin」（『古代詩集』所収）に由来。金髪の娘を牧歌的なスコットランドの情景に置いた内容。","features":"五音音階と全音階和声、旋法的な終止を組み合わせ、民謡のような素朴さを生んでいる。変格終止的な響きを多用し、旋律は順次進行と跳躍を交互に使う。第1巻の中でも技巧的に平易な部類で、荒れた第7曲「西風の見たもの」の直後に置かれ、対照が際立つ。","structure":[["冒頭主題","3音の短い動機で始まり、終止は変格（プラガル）進行。"],["第2の旋律（5〜6小節）","スコットランドの民謡やグリーグ風とも評される旋律が現れる。"],["頂点（19〜22小節）","クレッシェンドで盛り上がり、第22小節の終わりで頂点に達する。"],["ドローン風の部分（24〜27小節）","弱音で、平行して動く持続音的な響きが続く。"],["コーダ","冒頭主題が1オクターヴ上で戻り、変ト長調の和音で静かに閉じる。"]]},"asset":"assets/impressive/flaxen-hair.webp","focus":[0.5,0.48],"motion":"foliage","medium":"painting","focusPortrait":[0.5,0.48],"protect":[0.3,0.17,0.4,0.66]},{"id":"arabesque-1","title":"アラベスク第1番（2つのアラベスクより）","artist":"monet","subject":"Willow branches curve above a narrow river, reflected vines and water making a natural interlacing path through a deep green garden; no ornamental vector patterns.","rationale":"自然にかなう曲線というアラベスクの考えと、左右の流れる分散音型から柳と水の交差を選んだ。モネの反射と色の重なりで、輪郭線を描き足さず曲線を感じさせる。","source":"songs/arabesque-1.md","evidence":{"summary":"流れる装飾的な音型と柔らかな和声が特徴の、若きドビュッシーによる初期ピアノ曲。","nameOrigin":"アラベスク（唐草模様）に由来。ドビュッシーは、自然の理にかなった曲線の美を音楽に重ねた。","features":"和音の平行移動や五音音階を使い、調性感を柔らかく揺らす。流れる装飾的な音型が全体を貫き、アラベスクの名にふさわしい曲線的な線を描く。","structure":[["A部","第1転回形の三和音を平行に動かす書き出し。続いて左手のアルペッジョと右手のホ長調五音音階の下降。"],["B部","やや静かなイ長調。E–D–E–C♯の動機で始まる。"],["B部の終わり","同じ動機をハ長調に移してフォルテで力強く示す。"],["A部の再現","途中で高音域へ移って下り、五音音階の大きな上行・下行を経てホ長調に戻る。"]]},"asset":"assets/impressive/arabesque-1.webp","focus":[0.5,0.48],"motion":"water","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"prelude-bwv846","title":"平均律クラヴィーア曲集第1巻 第1番 前奏曲 ハ長調","artist":"pissarro","subject":"An ordered kitchen garden in morning light, repeated rows of green beds and a central path, the same simple wooden stakes taking different colors with distance.","rationale":"同じ分散和音型を保ったまま和声が変わる構造を、規則的な畝に異なる光が差す風景へ読む。ピサロの秩序ある平面構成と密な小筆触を選んだ。","source":"songs/prelude-bwv846.md","evidence":{"summary":"分散和音だけで織られた、平均律第1巻の幕開けの前奏曲。グノーのアヴェ・マリアの土台としても知られる、静かで澄んだ名曲。","nameOrigin":"「平均律」は曲集全体の題名で、全24の調による前奏曲とフーガを収めることに由来する。","features":"ほぼ全体が分散和音の同じ形の繰り返しで、旋律線が目立たない。そのぶん和声の色合いの変化がはっきり聞こえる。全35小節と短く、鍵盤楽器の入門から鑑賞まで幅広く親しまれている。","structure":[["冒頭(1小節〜)","ハ長調の主和音を分散和音で示して始まる。"],["中間部","和音の連なりで転調を重ね、緊張感を高めていく。"],["終結部","主音の保続音の上で和音が静かに収束する。"]]},"asset":"assets/impressive/prelude-bwv846.webp","focus":[0.5,0.48],"motion":"light","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"pavane","title":"亡き王女のためのパヴァーヌ（ピアノ原曲）","artist":"degas","subject":"An imagined old palace rehearsal hall, a young royal figure in a modest long court dress seen at a distance making a slow pavane step, dark polished floor and tall muted windows; no funeral.","rationale":"ラヴェルが語った昔の宮廷の王女の舞踏という想像から、ゆっくりした一歩を描く。特定の王女の葬送ではなく、ドガの人物の重心とパステルの距離感で古風さを出す。","source":"songs/pavane.md","evidence":{"summary":"古い舞曲の趣と静かな哀感を湛えた、ラヴェル初期の代表的ピアノ小品。","nameOrigin":"ラヴェルは、昔のスペイン宮廷で幼い王女が踊ったかもしれないパヴァーヌの情景だと説明した。一方で、題は語の響きが気に入って付けただけだとも語っている。特定の王女の追悼ではない。","features":"古風でほぼ素朴な和声と、抑えた表情、どこか遠い旋律の美しさが特徴。演奏時間は約6〜7分で、後に管弦楽版も書かれ、ホルンが主旋律を担う。","structure":[["全体像","楽章・部分ごとの詳細な構成は出典で確認できなかった（未確認）。"]]},"asset":"assets/impressive/pavane.webp","focus":[0.5,0.48],"motion":"light","medium":"pastel","focusPortrait":[0.54,0.48]},{"id":"nocturne-20","title":"ノクターン第20番 嬰ハ短調 遺作(レント・コン・グラン・エスプレッシオーネ)","artist":"caillebotte","subject":"An unoccupied rented room at blue dusk, a closed travel case and a chair before a tall window, a distant warm reflection on another roof; structured cool greys with a small warm ending.","rationale":"姉のための小品と、過去の協奏曲・歌曲の断片を引く回想性から、旅先の部屋と故郷を想う窓を選んだ。カイユボットの明確な空間に、長調の終止に似た小さな暖色を残す。","source":"songs/nocturne-20.md","evidence":{"summary":"ウィーン到着直後の1830年、姉のために書かれたノクターン。協奏曲の断片を引用した回想的な小品で、映画『戦場のピアニスト』の冒頭でも流れる。","nameOrigin":"ショパン自身は『ノクターン』とも番号とも付けていない。遺作として刊行された初版の題は『アダージョ』で、姉ルドヴィカの整理(夜想曲風のレント)を通じてノクターンとして定着し、通称の『レント・コン・グラン・エスプレッシオーネ』は楽譜の速度標語に由来。『追憶(Reminiscence)』の別名は望郷の曲とする解釈に基づく。生前出版のノクターンは18曲で、本作は含まれず『第20番』は後世の通し番号。","features":"哀愁をおびた旋律がゆったりした左手のアルペジオに乗って歌われ、ショパンの初期ノクターンの特徴をよく示す。後半では協奏曲や歌曲からの引用が次々に現れ、郷愁を帯びた回想のような趣を生む。最後は短調の曲でありながら長調の和音で結ばれ、悲しみの中にかすかな救いが残る。技巧的には、中間部の細かな装飾音形がやや目立つ程度で、全体として演奏のしやすさと表現の深さを両立している。","structure":[["序奏(1〜4小節)","静かな導入のあと、5小節目から主要旋律が始まる。"],["主部A","左手の流れるアルペジオの上で、息の長い歌が展開する。"],["中間部B","協奏曲第2番(第3楽章の主題・第1楽章の第2主題)と歌曲「乙女の願い」の断片を引用。"],["再現A'","冒頭の主題が戻り、最後は嬰ハ長調の和音で静かに閉じる。"]]},"asset":"assets/impressive/nocturne-20.webp","focus":[0.5,0.48],"motion":"light","medium":"painting","focusPortrait":[0.34,0.48]},{"id":"pathetique-2","title":"ピアノソナタ第8番「悲愴」 第2楽章","artist":"renoir","subject":"A sheltered garden bench under broad trees after a shower, a quiet seated adult in a pale shawl and warm reflected light, the dark paths remaining beyond the shelter.","rationale":"激しい両端楽章の間にある歌う緩徐楽章として、暗い道から少し離れた休息の場所を描く。ルノワールの暖かな木漏れ日と人間の量感を安らぎに結びつける。","source":"songs/pathetique-2.md","evidence":{"summary":"激しい両端楽章の間で、歌うような旋律が静かに広がる緩徐楽章。ベートーヴェンの優しさが最も親しまれた形で表れる一曲。","nameOrigin":"出版社が命名した「グランド・ソナタ・パテティーク」に由来。作曲者も気に入ったとされる。","features":"歌うような旋律が全体を貫く、ソナタ中で最も親しまれている緩徐楽章。激しい両端楽章とは対照的に、安らぎと温かさを湛えている。","structure":[["主部A","歌うような主旋律が静かに現れる。"],["中間部","やや動きのある部分で気分を変える。"],["主部の回帰","旋律が戻り、穏やかに結ばれる。"]]},"asset":"assets/impressive/pathetique-2.webp","focus":[0.5,0.48],"motion":"foliage","medium":"painting","focusPortrait":[0.37,0.48],"protect":[0.3,0.17,0.4,0.66]},{"id":"k331-1","title":"ピアノ・ソナタ第11番 イ長調 K.331 第1楽章（主題と6つの変奏）","artist":"morisot","subject":"A domestic window opening on a small terrace, six related small flowerpots and one quietly seated woman, the same simple shape altered by changing patches of light; airy whites and spare drawing.","rationale":"シチリアーナ風の穏やかな主題が六つの変奏へ姿を変えることから、同じ窓辺に並ぶ小さな反復と異なる光を選んだ。モリゾの軽い描き残しで装飾を過密にしない。","source":"songs/k331-1.md","evidence":{"summary":"ソナタの幕開けに変奏曲を置いたモーツァルトの異色作。ゆれるシチリアーナ風の主題が6通りに姿を変え、第3楽章のトルコ行進曲へ続く。","nameOrigin":"通称「トルコ行進曲付き」は第3楽章にモーツァルト自身が付けた「Alla turca（トルコ風に）」の指示に由来する。トルコ軍楽隊（イェニチェリ）の響きを模したもので、第1楽章自体に愛称はない。","features":"ソナタの冒頭楽章に変奏曲を置いたため、典型的な急速なソナタ形式の幕開けを避けた作品となった。主題はゆれるシチリアーナ風の6/8で、変奏が進んでも8小節＋10小節の形は変わらず、短調への転換、手の交差、遅いテンポの変奏、速い終結変奏と、表情だけが次々に変わる。第3楽章のトルコ行進曲の人気に隠れがちだが、全体の入口として穏やかな性格を担う。","structure":[["主題（Andante grazioso）","8小節＋10小節それぞれにリピートが付く2部構成。この枠組みが全変奏で保たれる。"],["第1・第2変奏","上声の装飾、続いて3連16分音符の伴奏上での旋律装飾。"],["第3変奏","イ短調に転じ、音階的な装飾が続く。第3楽章の動機との近さも指摘される。"],["第4・第5変奏","第4は手の交差を伴う華やかな変奏。第5は初めてAdagioに落とし、細かな装飾を加える。"],["第6変奏","4/4拍子のAllegroに変わり、終結部の役割を果たす。"]]},"asset":"assets/impressive/k331-1.webp","focus":[0.5,0.48],"motion":"foliage","medium":"painting","focusPortrait":[0.7,0.48],"protect":[0.3,0.17,0.4,0.66]},{"id":"prelude-7","title":"前奏曲第7番 イ長調 Op.28-7","artist":"pissarro","subject":"A very small rustic breakfast table near a cottage door, plain earthen jug, bread and a folded cloth, with a glimpse of a village lane; compressed warm earth colors and green.","rationale":"約45秒の一息のマズルカ風小品から、日常の小さな一場面を選んだ。ピサロの土の色と確かな物の配置で、短さにふさわしい簡潔な世界を作る。","source":"songs/prelude-7.md","evidence":{"summary":"24の前奏曲の第7番。集中最短で、約45秒の素朴なマズルカ風の小品。短いが、穏やかな表情に満ちた愛らしい曲。","nameOrigin":"通称は未確認(ショパン自身は各曲に標題を付けていない)。日本では『イ長調の前奏曲』のように調で呼ばれることが多い。","features":"24の前奏曲の中でも特に短く、一息で終わる素朴な小品。楽譜の見た目もやさしく、和音の連なりが旋律を支える簡潔な書法で、ピアノ学習者にも親しまれる。形式的な展開はほとんどなく、一つの楽想がそのまま小さな世界を作る点にショパンの前奏曲らしさがある。他の作曲家も本曲を素材に使っている(モンポウ『ショパンの主題による変奏曲』など)。","structure":[["全体像","集中最短の小品で、約45秒。マズルカ風の性格を持つ。"],["主題","付点リズムを含む素朴で短い旋律が、穏やかな和声に乗って歌われる。"],["後半","主題の変化型が現れ、終わりへ向かって静かに収束する。"]]},"asset":"assets/impressive/prelude-7.webp","focus":[0.5,0.48],"motion":"light","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"brahms-waltz-15","title":"16のワルツ Op.39 第15番 変イ長調（ピアノ独奏版）","artist":"renoir","subject":"One couple dancing closely on a modest lamplit terrace, the rest of the room suggested by a few dark silhouettes; rounded fabric, warm gold, indigo and rose.","rationale":"連弾から独奏へ広まった親密で揺れるワルツから、祝祭の大群衆ではなく一組の緩やかな踊りを選んだ。ルノワールの身体の重さと柔らかな色で三拍子を受け止める。","source":"songs/brahms-waltz-15.md","evidence":{"summary":"ブラームスの16のワルツの中でも最も愛される1曲。ゆるやかに揺れる旋律が、連弾から独奏に編まれて広く親しまれた。","nameOrigin":"曲名はないが、「ブラームスのワルツ」「ブラームスのワルツ第15番」として単独で親しまれる。","features":"優しくゆれる旋律で知られる、16曲中で最も有名なワルツ。ウィーンの舞曲の流行を背景にした親しみやすい小品で、独奏版は難しい版と簡易版があるため、学習者から演奏者まで幅広く弾かれている。","structure":[["作品集の位置","16曲の小さなワルツのうち第15番。連弾版はイ長調、難しい独奏版は変イ長調。"],["版の違い","ブラームス自身が独奏用に難しい版と易しい版の2つを編曲した。簡易版はイ長調。"],["形式","作品集の大半は、前半が属調などへ向かい、後半が展開風に始まって主題と主調へ戻る反復付き2部形式。"]]},"asset":"assets/impressive/brahms-waltz-15.webp","focus":[0.5,0.48],"motion":"light","medium":"painting","focusPortrait":[0.57,0.48]},{"id":"mendelssohn-spring-song","title":"無言歌集 第5巻 Op.62-6「春の歌」","artist":"monet","subject":"A newly blooming orchard after early spring rain, light scattered along a central rising path, small birds suggested by a few convincing touches, fresh green and lemon-white blossoms.","rationale":"歌詞のない歌の明るい旋律と小さな装飾から、芽吹きと光が先に春を告げる果樹園を選んだ。モネの花を一枚ずつ縁取らない色面で軽快さを作る。","source":"songs/mendelssohn-spring-song.md","evidence":{"summary":"歌詞のない歌をめざした無言歌集の中で最も親しまれる一曲。明るいイ長調の旋律に春のきざしを重ねた小品。","nameOrigin":"「春の歌」は楽譜冒頭の発想標語（春の歌のように、の意）に由来すると日本語の解説にある。48曲中、作曲者自身の題と確認できるのは5曲のみで、他は出版社の付題か発想標語由来。英国での別名「カンバーウェル・グリーン」は作曲地とされる地名から。","features":"歌詞のない器楽曲でありながら、歌い手に語らせるような抒情を目指した無言歌の代表作。明るいイ長調の旋律に、小音符の装飾的な動きが添えられ、春の軽やかさを思わせる。技巧は高度ではなく、アマチュアにも弾きやすいことが曲集全体の人気を支えた。ヴァイオリンやフルートなど他楽器への編曲も多く、日本では駅の発車メロディとしても使われている。","structure":[["曲集内の位置","第5巻（Op.62）の第6曲で、巻の締めくくり"],["調と速度","イ長調、Allegretto grazioso"],["演奏時間","約2分半（PTNA）"],["技巧上の焦点","小音符で書かれた装飾的な音型を旋律にどう溶け込ませるかが課題とされる（PTNA）"]]},"asset":"assets/impressive/mendelssohn-spring-song.webp","focus":[0.5,0.48],"motion":"foliage","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"goldberg-aria","title":"ゴルトベルク変奏曲 アリア","artist":"pissarro","subject":"A secluded walled garden seen from an open doorway, ordered stone steps descending to a small still fountain, the path curves back toward the same doorway.","rationale":"変奏の出発点でも終着点でもあるアリアを、戻ってくる庭の道に重ねる。不眠の伯爵の逸話を史実として描かず、ピサロの安定した構築と静かな小筆触を選ぶ。","source":"songs/goldberg-aria.md","evidence":{"summary":"30の変奏の出発点となる、優美で静かなサラバンド風の主題。不眠の伯爵の逸話でも知られる、夜に寄り添う音楽。","nameOrigin":"1802年のフォルケルの伝記に基づく、ゴルトベルクが演奏したという逸話に由来するが、信憑性には疑問がある。","features":"優美で静かな舞曲風の主題で、装飾音に富んだ旋律線が特徴。変奏全体の出発点であり終着点でもあるため、全曲の枠を作る役割を持つ。聴く人を穏やかな気持ちにさせる落ち着いた曲想。","structure":[["アリア","サラバンド風の主題。装飾音の多い旋律を持つ。"],["30の変奏","アリアの低音の進行を土台に展開する。"],["アリア・ダ・カーポ","最後に冒頭のアリアが戻って閉じる。"]]},"asset":"assets/impressive/goldberg-aria.webp","focus":[0.5,0.48],"motion":"foliage","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"reverie","title":"夢（Rêverie）","artist":"morisot","subject":"A woman resting with an unopened book on a veranda, a curtain and empty pale space around her, distant green almost sketchily unfinished; no dream fantasy symbols.","rationale":"素朴な旋律美と夢想の題から、何かが起こる前の宙に浮いた日常を選んだ。モリゾの余白と見え隠れする輪郭を、音の内省と距離感に結びつける。","source":"songs/reverie.md","evidence":{"summary":"ドビュッシー本人は軽視したが、素朴な旋律美で広く愛されるようになった初期の小品。","nameOrigin":"フランス語で「夢想」を意味する題名。命名の経緯は未確認。","features":"ハリー・ハルブライヒは、素朴ながらも確かな旋律の魅力を持つ耳に心地よい曲と評した。単純な旋律美が中心の曲で、そのため多くの楽器へ編曲されている。","structure":[["全体像","小規模な小品。楽式の詳細は出典で確認できなかった（未確認）。"]]},"asset":"assets/impressive/reverie.webp","focus":[0.5,0.48],"motion":"light","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"gnossienne-1","title":"グノシエンヌ 第1番","artist":"degas","subject":"An empty plaster-walled passage in an old dance school, a weathered classical statue seen in profile and a doorway not fully visible, one oblique strip of ochre light on the floor.","rationale":"小節線のない自由な時間と、語源にある迷宮・舞踏の諸説から、行き先の定まらない廊下を選んだ。ドガの斜めの視線と色紙の暗部で、確かな床と曖昧な時間を併置する。","source":"songs/gnossienne-1.md","evidence":{"summary":"拍子も小節線もない自由な時間の中で、物憂い旋律が揺れる。サティが神秘思想に近づいた時期の、夜に似合う一曲。","nameOrigin":"語源には諸説ある。テセウスがミノタウロス退治を祝って踊ったという迷宮の舞踏を指す語(1865年のラルース辞典)や、グノーシス(認識)に由来するとの説がある。","features":"拍子記号や小節線がない自由な時間感覚の曲。単純な伴奏型と、東方的とも評される旋律が組み合わさり、夢うつつのような雰囲気を作り出している。","structure":[["冒頭","左手の伴奏型の上で、物憂げな旋律が現れる。"],["中間部","旋律の動きが少し変わり、自由な拍で進む。"],["終結","静かに音が消えるように閉じる。"]]},"asset":"assets/impressive/gnossienne-1.webp","focus":[0.5,0.48],"motion":"light","medium":"pastel","focusPortrait":[0.5,0.48]},{"id":"waltz-64-2","title":"ワルツ第7番 嬰ハ短調 Op.64-2","artist":"degas","subject":"Two adult ballet dancers in gauzy stage skirts waiting in the wings, one turning rapidly and one nearly still, rose and violet pastel against dark blue stage space.","rationale":"短調主題・急速な流れ・長調の歌の交替と、レ・シルフィードへの編曲から舞台袖を選んだ。ドガの素描と乾いたパステルで、異なる重心と速度を描き分ける。","source":"songs/waltz-64-2.md","evidence":{"summary":"哀愁の短調主題と長調の歌がめぐる、後期ショパンの代表的なワルツ。ロスチャイルド夫人に献呈。","nameOrigin":"通称は確認できなかった。日本では『第7番』の番号で呼ばれ、『小犬のワルツ』(Op.64-1)と並んで知られる。","features":"哀愁を帯びた短調の主題と、流れるような急速な部分、長調に転じた歌のような中間部が交替する、変化に富んだワルツ。長調の部分は夢見るように穏やかで、短調の主題が戻ると切なさが一層際立つ。管弦楽版がバレエ『レ・シルフィード』の一部になっている。","structure":[["主題A","テンポ・ジュストの和音的な旋律。歩くような感触の短調の主題。"],["主題B","より速く(più mosso)、8分音符の流れの中で進む。"],["主題C","より遅く(più lento)で、嬰ハ長調(変ニ長調)の歌。間奏のような性格。"],["全体構成","A B C B A B の順で現れ、ロンド風だがワルツの三部形式にも似る。"]]},"asset":"assets/impressive/waltz-64-2.webp","focus":[0.5,0.48],"motion":"light","medium":"pastel","focusPortrait":[0.82,0.48]},{"id":"waltz-69-1","title":"ワルツ第9番 変イ長調 Op.69-1『別れのワルツ』","artist":"caillebotte","subject":"A carefully observed empty chair beside a small table with a folded blank farewell letter, a half-open tall door and a cool courtyard beyond, quiet evening geometry.","rationale":"私的な手紙のような性格と、別れに贈ったとされる経緯に基づく。カイユボットの冷静な遠近法と存在感のある家具で、人の不在を描く。","source":"songs/waltz-69-1.md","evidence":{"summary":"1835年、マリア・ヴォジンスカとの別れに際して書かれたとされるワルツ。ショパンの死後、友人フォンタナが出版した。","nameOrigin":"『別れのワルツ(Farewell Waltz / Valse de l'adieu)』の呼称は、ショパン本人の命名ではない。1835年にマリア・ヴォジンスカとの別れの際に贈られた曲とされることに由来する。出版は死後1855年にフォンタナが行い、Op.69は本人が付けた作品番号ではなく、遺作として後から与えられたもの。","features":"冒頭の主題は、3拍子の流れの中で寂しさとなつかしさが交ざり合い、聴き手を一気に引き込む。中間の主題は軽やかで、陰りの合間に笑顔がのぞくような対比がある。ワルツの形を借りながら、踊るためというより、手紙のように個人的な感情を込めた作品。ショパンの死後に広まったこともあり、物語性のある呼称とともに愛されている。","structure":[["主題1","con espressione。憂いを帯びた懐かしい旋律で、小さな装飾音の上昇で一つの山を作る。"],["主題2","sempre delicatissimo。主題1よりやや明るく、すぐに第1主題に戻る。"],["主題3","dolce。最も軽やかで遊び心のある旋律。"],["主題4","二重音が段階的に上がっていく部分(poco a poco crescendo)で、3の主題に戻って、冒頭へ戻る(ダ・カーポ)。"]]},"asset":"assets/impressive/waltz-69-1.webp","focus":[0.5,0.48],"motion":"light","medium":"painting","focusPortrait":[0.64,0.48]},{"id":"tchaikovsky-october","title":"四季 Op.37a 第10曲 10月「秋の歌」","artist":"pissarro","subject":"A neglected garden with a central weathered gate, yellow leaves blown along a narrow path and bare orchard branches, rich earthy browns and cool muted green.","rationale":"荒れた庭の黄色い葉が風に舞うというエピグラフを直接の題材にする。ピサロの生活の残る土地と密な土色の筆触で、旋律の物悲しさを描く。","source":"songs/tchaikovsky-october.md","evidence":{"summary":"チャイコフスキーが雑誌の依頼で書いた十二か月の小品のうち、ニ短調で秋の寂しさを歌う10月の曲。","nameOrigin":"「秋の歌」の題は、依頼した編集者ニコライ・ベルナールの提案で、チャイコフスキーが受け入れたもの。エピグラフ（A・K・トルストイの詩句）もベルナールの選。","features":"ニ短調で、悲しげに十分に歌う、という発想標語が付く。四季の中でも特に物悲しい一曲として知られる。短い曲だが旋律が前面にあり、ロシアの秋の寂しさを歌曲のように描く。依頼仕事として書かれた小品集ながら、旋律の美しさから単独でもよく弾かれ、他の楽器への編曲も多い。","structure":[["標題とエピグラフ","「秋の歌」。A・K・トルストイの、荒れた庭に黄色い葉が風に舞う、という趣旨の詩句が添えられる"],["速度と調","Andante doloroso e molto cantabile、ニ短調、56小節"],["四季全体での位置","秋の中盤を担う10曲目。次の11曲目は「トロイカ」"],["原稿","10月を含む11曲の自筆譜はモスクワの国立音楽博物館に現存（4月のみ紛失）"]]},"asset":"assets/impressive/tchaikovsky-october.webp","focus":[0.5,0.48],"motion":"foliage","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"k310-2","title":"ピアノ・ソナタ第8番 イ短調 K.310 第2楽章 アンダンテ・カンタービレ・コン・エスプレッシオーネ","artist":"morisot","subject":"A calm pale room with a carafe and a loosely folded white cloth near a garden window, an empty chair at center, hard dark corridor only at the far edge.","rationale":"短調の両端楽章に挟まれたヘ長調の歌を、静かな光の休息として描く。母の死を直接描写する史実解釈は避け、モリゾの白い空間と軽い筆触を選ぶ。","source":"songs/k310-2.md","evidence":{"summary":"母の死の頃に書かれたイ短調ソナタの中央で、ヘ長調の歌が静かに流れる緩徐楽章。モーツァルトの数少ない短調ソナタの陰影を和らげる。","nameOrigin":"愛称はない。K.310/300dはケッヘル番号の旧番号と改訂番号の併記。","features":"両端楽章がイ短調の悲痛なソナタの中で、ヘ長調の穏やかな歌を聴かせる緩徐楽章。標語どおり旋律の歌い方が中心で、全曲の緊張を和らげる役割がある。母の死との関係はあくまで推測とされ、楽章ごとの具体的な感情表現と結びつける確かな出典は確認できなかった。","structure":[["ソナタ全体","第1楽章Allegro maestoso（イ短調4/4）、第2楽章Andante cantabile con espressione（ヘ長調3/4）、第3楽章Presto（2/4）の3楽章。"],["本楽章の位置","短調の両端楽章にはさまれたヘ長調の緩徐楽章。"],["発想標語","「歌うように、表情豊かに」を意味し、旋律の歌わせ方が主眼にある。"]]},"asset":"assets/impressive/k310-2.webp","focus":[0.5,0.48],"motion":"light","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"schubert-impromptu-90-3","title":"4つの即興曲 Op.90 D.899 第3番 変ト長調","artist":"sisley","subject":"A broad slow river bending into a pale distance, willows and one low stone bridge, long horizontal reflections carrying one small boat beneath an immense quiet sky.","rationale":"竪琴のような分散和音に乗る長い旋律を、途切れず進む川と細かい反射へ読む。シスレーの空と水路の明快な距離を用いて、旋律を一本の道として見せる。","source":"songs/schubert-impromptu-90-3.md","evidence":{"summary":"変ト長調の長い旋律が、竪琴のような分散和音に乗って流れるシューベルト晩年の歌。映画でもおなじみの一曲。","nameOrigin":"「即興曲（Impromptu）」という名称は、D.899の4曲についてはウィーンの出版社トビアス・ハスリンガーによるとされる（ドイツ語版Wikipedia）。通称の「秋」「夜」のような愛称は確認できなかった。","features":"静かな夜想曲風の歌で、長い旋律線と途切れない三和音の分散伴奏が続く。旋律は一貫して歌い、和声の移ろいが陰影を与える。同じ右手で旋律と伴奏を弾くピアノ的な魅力があり、映画の場面にもたびたび使われている。","structure":[["拍子と速度","Andante、4/2拍子（alla breve）。ゆったり流れる"],["旋律と伴奏","右手が旋律と伴奏を同時に受け持つ。5指が旋律を歌い、他の指が竪琴のような分散和音を奏でる"],["和声","旋律の下で、新しい和声の動きが加わり表情を変えていく"],["形式感","第1番や第3番は、展開部のない序曲形式に近い（ドイツ語版Wikipedia）"]]},"asset":"assets/impressive/schubert-impromptu-90-3.webp","focus":[0.5,0.48],"motion":"water","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"brahms-op118-2","title":"6つの小品 Op.118 第2番 間奏曲 イ長調","artist":"pissarro","subject":"A small late-season garden near a country lodging, a worn wooden bench and narrow path in warm ochre evening, deep green foliage and a few quiet windows.","rationale":"晩年の休暇先で生まれた優しく内省的な小品という解説から、使い込まれた庭の休息を選んだ。ピサロの確かな土地と日常の手触りで、秘めた温かさを出す。","source":"songs/brahms-op118-2.md","evidence":{"summary":"晩年のブラームスが静かな休暇先で書いた小品集の中の最も有名な1曲。優しく内省的な旋律で、秘めた想いのようだと語られる。","nameOrigin":"「間奏曲（インテルメッツォ）」は、小さな性格的小品に対する呼称。発想標語は「Andante teneramente（歩く速さで、優しく）」。","features":"Op.118のなかで最も知られる小品の一つで、晩年のブラームスの内省的な作風を代表する。ヘンレ社の難易度は6（中級）で、音楽的な深みに比べて技術的な負担は比較的軽い。映画『ラスト、コーション』(2007) のサウンドトラックにも収録された。","structure":[["曲集内の位置","Op.118の6曲のうち第2番。第1番イ短調（難易度7）、第3番バラード（7）、第4番へ短調（6）、第5番ロマンツェ（6）、第6番変ホ短調と続く。"],["発想標語","Andante teneramente。"],["内部構成","未確認（出典から確認できなかった）。"]]},"asset":"assets/impressive/brahms-op118-2.webp","focus":[0.5,0.48],"motion":"foliage","medium":"painting","focusPortrait":[0.35,0.48]},{"id":"canon","title":"カノン（パッヘルベルのカノン）","artist":"monet","subject":"Three poplars spaced in depth beside a river, their three reflections following one repeated current, patches of golden green and blue layered horizontally.","rationale":"二小節ずつ追いかける三声と固定された低音進行を、奥行きの違う三本の木と一つの流れへ読み替える。モネの水面の色の反復でカノンの重なりを表す。","source":"songs/canon.md","evidence":{"summary":"低音の同じ進行を繰り返し、3つの声が同じ旋律を追いかけて重なっていく、バロックの代表的なカノン。","nameOrigin":"正式名は「3つのヴァイオリンと通奏低音のためのカノンとジーグ」。一般には「パッヘルベルのカノン」「Canon in D」と呼ばれる。","features":"ほぼ同じ低音進行を繰り返し、その上に3声が同じ旋律を時間差で重ねる。厳格な模倣であるカノンと、低音が固定された変奏曲（シャコンヌ的）の二つの形式が一曲に重なる点が特色。和声進行はロマネスカ型とされ、のちのポップスにも多く転用された。上声が少しずつ細かく動いて曲が盛り上がるので、同じ和音の繰り返しでも飽きずに聴ける。","structure":[["カノン","同じ旋律を2小節ずらして3つのヴァイオリンが追う。低音は8つの和音（D-A-Bm-F#m-G-D-G-A）を繰り返す。"],["変奏","低音の28回の反復の上で、4分音符、8分音符、16分音符と音価が細かくなり、付点やシンコペーションも現れる。"],["ジーグ","12/8拍子、各10小節の2部分。カノンと違い固定低音はなく、模倣的な書法で進む。"]]},"asset":"assets/impressive/canon.webp","focus":[0.5,0.48],"motion":"water","medium":"painting","focusPortrait":[0.55,0.48]},{"id":"air-g-string","title":"G線上のアリア","artist":"sisley","subject":"A long low riverbank path, one slender boat tethered beneath a stone arch, a low walking rhythm of paving stones and high continuous pale sky.","rationale":"息の長い旋律と歩む低音の対比を、空の連続と川岸の歩幅へ結びつける。シスレーの澄んだ空間と水平の水の筆触で、旋律と支えを描き分ける。","source":"songs/air-g-string.md","evidence":{"summary":"バッハの管弦楽組曲の緩徐楽章を、ウィルヘルミがG線だけで弾けるよう編曲した、静かに歌う名旋律。","nameOrigin":"ウィルヘルミが譜面に「G線で」と書いたことに由来する。のちに「原曲からG線だけで弾く曲だった」という誤った話も流れた。","features":"原曲は、重なり合う高音の旋律線と、歩むように進む低音との対比が魅力。ウィルヘルミ版は旋律を低音域の独奏に任せ、他を弱くしたため、原曲の対位法的な織り込みや低音の推進力は薄れ、よりロマン派的な甘く暗い響きになった。ヨアヒムは「バッハ作品の恥知らずな改竄」と批判し、トーヴィーも原曲のニ長調で演奏すべきだとした。それでも編曲の名は、さまざまな楽器の版で通称として定着している。","structure":[["旋律","高音弦の絡み合う旋律が、ゆったりとした長い息で歌われる。"],["低音","原曲では低音が規則的に歩み、曲に推進力を与える。"],["ウィルヘルミ版","旋律をG線の低音域に移し、伴奏は弱音器や弱いピツィカートに抑える。"]]},"asset":"assets/impressive/air-g-string.webp","focus":[0.5,0.48],"motion":"water","medium":"painting","focusPortrait":[0.32,0.48]},{"id":"jesu-joy","title":"主よ人の望みの喜びよ","artist":"pissarro","subject":"A small village church beyond an orchard in gentle morning, a winding path and ordinary people walking quietly toward an open door, warm green and chalk white.","rationale":"コラールの歌と独立した流れる伴奏から、礼拝へ向かう人と途切れない道を選んだ。ピサロの生活と土地を観察する視線で、喜びを日常の光へ置く。","source":"songs/jesu-joy.md","evidence":{"summary":"バッハのカンタータのコラールを、マイラ・ヘスがピアノ用にまとめた、流れるような伴奏に旋律が歌う名編曲。","nameOrigin":"英語題「Jesu, Joy of Man's Desiring」はヘス版に付いた題で、原曲のどちらの歌詞とも一致しない。日本語題はそれに基づく。","features":"原曲では、コラール旋律の合唱に、独立した器楽の流れる旋律がからむ。ヘス編曲はその両方を一台のピアノにまとめ、「素朴に、流れるように」と指示されている。弾きやすそうに聞こえて、内声の流れと旋律を同時に整えるのは容易でない。結婚式やアドベント、クリスマス、イースターなどでよく演奏される。","structure":[["主旋律","ピアノ右手の旋律がコラールを歌う。"],["伴奏","絶え間なく流れる三連系の動きが、曲全体を支える。"],["原曲との関係","原曲は合唱＋トランペット・ヴァイオリン・通奏低音（オーボエ・ヴィオラは任意）。"]]},"asset":"assets/impressive/jesu-joy.webp","focus":[0.5,0.48],"motion":"foliage","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"rach-pc2-2","title":"ピアノ協奏曲第2番 第2楽章","artist":"monet","subject":"A river thawing into spring light, dark banks opening toward a luminous central distance, small intricate water touches around one long calm reflected cloud.","rationale":"治療後に創作へ戻った経緯と、ハ短調から遠いホ長調へ開く冒頭、木管とピアノの受け渡しから、解ける水と開ける光を選んだ。モネの色面を回復の比喩として用いる。","source":"songs/rach-pc2-2.md","evidence":{"summary":"ダーリ医師の治療で立ち直ったラフマニノフが書いた、静かで抒情的な緩徐楽章。映画や歌にも転用された名旋律。","nameOrigin":"楽章名はAdagio sostenuto（ゆっくりと音を保って）。楽章名以外の通称は未確認。","features":"第1楽章のハ短調から、遠隔のホ長調へ移り、弦の和音で静かに幕を開ける。ピアノは旋律をオーケストラ（特にフルートやクラリネットなどの木管）と受け渡しながら、細やかな音型で支える役割も担う。協奏曲全体の中で最も抒情的で、のちにポピュラー音楽にも転用された旋律をもつ。","structure":[["導入","弦楽器の遅い和音が、ハ短調からホ長調へ転調して始まる。"],["A部","ピアノが静かな伴奏音型を奏で、木管が旋律を歌う。"],["中間部","Più animato。ピアノの動きが活発になり盛り上がる。"],["再現","テンポが戻り、主題が回帰して静かに終わる。"]]},"asset":"assets/impressive/rach-pc2-2.webp","focus":[0.5,0.48],"motion":"water","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"schubert-ave-maria","title":"アヴェ・マリア（エレンの歌 第3番）","artist":"monet","subject":"A quiet Scottish-like lakeshore near a rocky shelter, one small fully clothed woman in prayer beneath trees, water and mist enclosing her rather than a church icon.","rationale":"湖上の美人のエレンが祈る詩と六連符の伴奏に基づき、湖と岩陰を選んだ。モネの大気と水で人物を包み、典礼の聖母像と物語の祈りを混同しない。","source":"songs/schubert-ave-maria.md","evidence":{"summary":"スコットの詩に付けられた祈りの歌を、リストがピアノ一台で歌わせた編曲。息の長い旋律が夜に寄り添う。","nameOrigin":"歌詞冒頭と各連末の呼びかけ「Ave Maria」から。『湖上の美人』ゆえ、初演先の伯爵夫人自身も「湖上の美人」と呼ばれたとされる。","features":"原曲は変ロ長調で、持続低音と六連符の伴奏に息の長い旋律が乗る簡素な歌。リストの独奏版は原曲の構成にほぼ忠実で、旋律を中音域に置き、上下の音域を和音や分散和音で囲むため、三本の手で弾くような響きになる。派手な技巧曲ではないが、多層の音色と分散和音の処理に、高度な技術と音楽性が求められる。","structure":[["第1連","穏やかな分散和音に乗り、祈りの旋律が始まる。"],["第2〜3連","同じ旋律を保ちつつ、詩の内容に応じて表情が変わる。"],["リスト版の中間部","和音の伴奏が分散和音に替わり、高音域で静かに輝く。"],["リスト版の頂点と結び","感情が最も高まったのち、再び静けさに戻る。"]]},"asset":"assets/impressive/schubert-ave-maria.webp","focus":[0.5,0.48],"motion":"water","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"liebesgruss","title":"愛のあいさつ","artist":"renoir","subject":"An engaged couple quietly exchanging a small ribbon-tied gift on a garden terrace, believable hands at the center, warm reflected skin and blue-green leaf shadows.","rationale":"婚約者アリスへの贈り物という作曲経緯から、贈り物を渡す親密な動作を選んだ。ルノワールの人の肌と布の量感で、甘さを生きた身振りとして描く。","source":"songs/liebesgruss.md","evidence":{"summary":"エルガーが婚約者アリスへの贈り物として書いた小品。甘く温かな旋律で、ピアノ独奏版でも親しまれている。","nameOrigin":"最初の題は独語のLiebesgruss。出版時に、欧州各国で売りやすいよう仏語題Salut d'Amourが主題となり、Liebesgrussは副題に回った。","features":"確認できた出典では、旋律構成や和声の分析は得られなかった。分かっているのは、原曲がヴァイオリンとピアノのための小品で、ホ長調で書かれたことである。婚約者への贈り物として作られた個人的な作品でありながら、のちに多くの楽器編成へ編曲され、エルガーの代表作の一つとなった。","structure":[["原曲の編成","ヴァイオリンとピアノ。ピアノ独奏版は、エルガー自身の自筆譜に基づく公認版の一つ。"],["管弦楽版初演","1889年11月11日、水晶宮でのオーケストラ版。"],["版の展開","ヴァイオリン、ピアノ独奏、チェロ、小管弦楽の各版が初版時に出た。"]]},"asset":"assets/impressive/liebesgruss.webp","focus":[0.5,0.48],"motion":"foliage","medium":"painting","focusPortrait":[0.5,0.48],"portraitAsset":"assets/impressive/liebesgruss-portrait.webp"},{"id":"vocalise","title":"ヴォカリーズ","artist":"monet","subject":"A single broad pale cloud reflected across an unbroken expanse of water, almost no hard horizon, cool blue-green underneath a continuous pearl-grey sweep.","rationale":"言葉を持たず母音だけで歌う長い旋律から、名前や物語を付けすぎない連続した雲と反射を選んだ。モネの輪郭を溶かす筆触で、一息の長さを視覚化する。","source":"songs/vocalise.md","evidence":{"summary":"歌詞を持たず母音だけで歌われるラフマニノフの歌曲。ピアノ独奏を含む多彩な編曲で親しまれている。","nameOrigin":"ヴォカリーズとは、歌詞を持たず母音だけで歌う歌唱法・曲種のこと。","features":"歌詞の代わりに一つの母音で歌う、語らない歌曲である。そのため旋律の力だけで聴かせる曲となり、管弦楽、弦楽器、管楽器、ギターなど非常に多くの楽器に編曲されている。ピアノ独奏版では旋律と伴奏を一人で弾き分ける必要がある（構造欄は、詳細な出典を確認できず概略のみ）。","structure":[["旋律","息の長い主旋律が、低めの伴奏の上で歌われる。"],["展開","旋律が高まりながら音域を広げる。"],["終結","静かに収束する。"]]},"asset":"assets/impressive/vocalise.webp","focus":[0.5,0.48],"motion":"water","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"brahms-lullaby","title":"ブラームスの子守歌","artist":"cassatt","subject":"A mother beside a sleeping infant in a wooden cradle, seen from a high close angle, a patterned coral blanket, sage-green furniture and warm cream, rocking diagonals.","rationale":"誕生を祝う私的な歌と、ゆりかごのようなシンコペーションに基づく。カサットの高い視点と平面的な色、観察的で過度に感傷的でない母子像を選んだ。","source":"songs/brahms-lullaby.md","evidence":{"summary":"友人の子の誕生を祝って書かれた、世界で最も有名な子守歌のひとつ。揺れる伴奏に素朴な旋律が乗る。","nameOrigin":"Wiegenliedはドイツ語で「子守歌」。日本では「ブラームスの子守歌」と呼ばれ、歌い出しから「Guten Abend, gut' Nacht」とも呼ばれる。","features":"素朴な旋律と、ゆりかごを揺らすようなシンコペーションの伴奏が一体となった短い歌。低音に変ホ音が保たれ、安らぎを生む。一見とても簡素だが、旋律に別の歌を隠し重ねた工夫があるとされる。1877年には交響曲第2番第1楽章の第2主題にも、この旋律の形が使われた。","structure":[["伴奏型","ゆりかごを思わせるシンコペーションの音形が全曲を支える。"],["低音","変ホ音が持続して、落ち着きを表す。"],["第1連","『少年の魔法の角笛』の詩（Guten Abend, gut' Nacht）。"],["第2連","ゲオルク・シェーラーの詩を、後から追加。"]]},"asset":"assets/impressive/brahms-lullaby.webp","focus":[0.5,0.48],"motion":"light","medium":"painting","focusPortrait":[0.5,0.48],"portraitAsset":"assets/impressive/brahms-lullaby-portrait.webp"},{"id":"mozart-pc21-2","title":"ピアノ協奏曲第21番 第2楽章","artist":"monet","subject":"A small still boat on a pale river at early morning, gauzy willow reflections and thin repeating ripples, green-grey and soft silver, no people in close view.","rationale":"弱音器付きの弦、三連符の反復、夢見るピアノから、音を抑えた水上の朝を選んだ。映画の悲劇を直接再現せず、モネの淡い層で三部の移ろいを表す。","source":"songs/mozart-pc21-2.md","evidence":{"summary":"弱音器付きの弦と夢見るようなピアノが続く緩徐楽章。映画『みじかくも美しく燃え』で世界的に知られた。","nameOrigin":"通称「エルヴィラ・マディガン」は、1967年のスウェーデン映画『みじかくも美しく燃え』（原題Elvira Madigan）でこの楽章が使われたことによる。","features":"この楽章は3つの部分から成り、冒頭の管弦楽部分に楽章の主要な旋律素材がすべて含まれている。弱音器付き弦の上で、夢を見るような旋律が三連符の反復音とピツィカートに支えられて進む。ピアノが入ってからは、ヘ長調やヘ短調など調を巡る展開があり、変イ長調での再現を経て静かに終わる。","structure":[["第1部","管弦楽のみ。弱音器付きの弦。第1ヴァイオリンの夢見るような旋律に、第2ヴァイオリンとヴィオラの三連符の反復、チェロとバスのピツィカート。楽章の主要な旋律素材はすべてここで提示される。"],["第2部","ピアノが加わりヘ長調で始まる。単純な反復ではなく、新しい素材が挟まり転調していく（ハ短調・ハ長調、ト短調、変ロ長調を経てヘ短調へ）。"],["第3部","同じ旋律が変イ長調で再現される。その後ヘ短調からヘ長調へ戻り、短いコーダで閉じる。"]]},"asset":"assets/impressive/mozart-pc21-2.webp","focus":[0.5,0.48],"motion":"water","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"faure-apres-un-reve","title":"夢のあとに","artist":"morisot","subject":"An empty bed just after dawn, loosely folded linen and a pale curtain at a half-open window, a second pillow and an empty patch of morning light.","rationale":"夢の中の逢瀬が消えた後の喪失という詩の内容を、起床後の不在として描く。モリゾの白地と描き残した輪郭で、夢の余韻と現実の空間をつなぐ。","source":"songs/faure-apres-un-reve.md","evidence":{"summary":"フォーレがビュシーヌの詩に付けた1877年の歌曲。夢の余韻と喪失を歌い、チェロ版などでも愛される。","nameOrigin":"題は詩の内容、つまり夢から覚めたあとの喪失感に由来する。","features":"この曲は歌曲として書かれたが、器楽曲としても広く演奏される。詩は夢から覚めた者の独白で、情熱的な夢と、それが消えたあとの喪失感を扱う。IMSLPにはテノールまたはチェロとピアノのための版があり、旋律を歌う声部をチェロが担う編曲として演奏される。調性、拍子、旋律の具体的な分析は、出典から確認できなかった。","structure":[["歌曲集での位置づけ","『3つのメロディ』Op.7の第1曲。IMSLPによる作曲年は第1曲1877年、第2曲1870年頃、第3曲1873年。"],["詞","ロマン・ビュシーヌ作。イタリア語の詩に基づく。夢の中の逢瀬と、そこへ戻りたいという願いを語る独白。"],["器楽版","IMSLPに、チェロとピアノ版（リュッター編、コウロン編、プラティチェッリ編）が掲載されている。"]]},"asset":"assets/impressive/faure-apres-un-reve.webp","focus":[0.5,0.48],"motion":"light","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"paganini-var18","title":"パガニーニの主題による狂詩曲 第18変奏","artist":"monet","subject":"A low arched stone footbridge and its perfectly legible inverted reflection in a quiet pond, soft wide bands of gold light opening from cool blue water.","rationale":"主題を反転して生まれた旋律という仕組みを、橋と上下逆の反射へ結びつける。モネの反射の色面を用い、有名な既存の橋の絵は複製しない。","source":"songs/paganini-var18.md","evidence":{"summary":"パガニーニの主題を反転させて生まれた、ラフマニノフ屈指の甘美な旋律。映画でも使われた名変奏。","nameOrigin":"パガニーニの奇想曲第24番の主題に基づくことから。","features":"全曲の中で最も有名な変奏で、単独で名曲集に収録されることが多い。パガニーニの主題をいわば逆さにした旋律を、変ニ長調の甘美な響きで歌う。全体が速い変奏で構成される中で、この変奏だけが穏やかな抒情を担い、全曲のハイライトとなっている。","structure":[["全体の位置","全体を協奏曲の3楽章に見立てると、第11〜18変奏が緩徐楽章に相当する。"],["第18変奏","主題を反転させた旋律が、イ短調から変ニ長調で歌われる。"],["直後","第19変奏以降は終楽章に相当し、速い変奏が続く。"]]},"asset":"assets/impressive/paganini-var18.webp","focus":[0.5,0.48],"motion":"water","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"solveigs-song","title":"ソルヴェイグの歌","artist":"pissarro","subject":"A small Nordic wooden cottage with a woman waiting at a lit window, a still path receding toward dark fir trees and cool distant hills, restrained earth and green tones.","rationale":"帰らぬ人を故郷で待ち続けるソルヴェイグの歌から、窓の灯と誰も通らない道を選んだ。ピサロの生活の場を捉える構築で、待つ時間の長さを描く。","source":"songs/solveigs-song.md","evidence":{"summary":"帰らぬ人を待ち続けるソルヴェイグの歌を、グリーグ自身がピアノ独奏に編曲。北欧の哀愁を静かにたたえた旋律。","nameOrigin":"ヒロインであるソルヴェイグ（Solveig/Solvejg）の名から。故郷でペールを待ち続ける女性の歌である。","features":"待ち続ける女性の心を歌う、哀愁を帯びた短調の旋律が核。グリーグ自身がピアノ独奏に編曲したOp.52-4は、歌の旋律と伴奏をピアノ一台に収める。同じ劇の第5幕には「ソルヴェイグの子守歌」もあり、組曲にはこの歌の方が採られた。","structure":[["全体","イプセン劇第4幕で歌われる、待ち続ける女性の歌。"],["Op.52-4","イ短調、Poco Andanteのピアノ独奏編曲。"],["組曲版","組曲第2番Op.55の第4曲に収録。"],["関連曲","第5幕の「ソルヴェイグの子守歌」。"]]},"asset":"assets/impressive/solveigs-song.webp","focus":[0.5,0.48],"motion":"foliage","medium":"painting","focusPortrait":[0.35,0.48],"protect":[0.3,0.17,0.4,0.66]},{"id":"beethoven-5","title":"交響曲第5番 ハ短調 作品67「運命」第1楽章","artist":"guillaumin","subject":"A wind-struck riverside road under a lowering violet sky, three close short poplars and one long towering tree creating a short-short-short-long rhythm, copper earth and a diagonal dark river.","rationale":"四音の動機を徹底して展開する第1楽章から、三つの短い樹形と一つの長い樹形を構図の骨格にする。ギヨマンの厚い強色で圧縮された力を描く。","source":"songs/beethoven-5.md","evidence":{"summary":"「ダダダダーン」の4音の動機を徹底的に展開した、ハ短調の緊迫したソナタ形式の楽章。ベートーヴェンの代名詞ともいえる冒頭で知られる。","nameOrigin":"「運命」はドイツ語の Schicksalssinfonie に由来する通称で、ベートーヴェン自身の題ではない。冒頭の動機について「運命はこのように扉をたたく」と語ったとする話は、秘書シンドラーの証言に基づくが、シンドラーの証言の信頼性には疑問が多く、実際に語ったかは不確か。第二次世界大戦後には「勝利の交響曲」と呼ばれたこともある。","features":"ごく短い動機を徹底的に展開して楽章全体を組み立てている点が最大の特徴。全曲では、終楽章でピッコロ、コントラファゴット、トロンボーンが加わる（第9番や第6番など他の交響曲でも使用）。第3楽章から第4楽章へは切れ目なく続く。","structure":[["提示部","「短・短・短・長」の4音の動機（ダダダダーン）で始まり、この動機が第1主題となる。ホルンの呼びかけを挟んで第2主題が現れる。"],["展開部","動機がさまざまな楽器間で受け渡され、調を変えながら緊張を高めていく。"],["再現部","冒頭動機が再現され、途中でオーボエの短い独奏が入る。"],["コーダ","動機がさらに展開されたのち、力強い和音で楽章を結ぶ。"]]},"asset":"assets/impressive/beethoven-5.webp","focus":[0.5,0.48],"motion":"foliage","medium":"painting","focusPortrait":[0.56,0.48]},{"id":"beethoven-9","title":"交響曲第9番 ニ短調 作品125「合唱付き」第4楽章「歓喜の歌」","artist":"renoir","subject":"A long outdoor table with ordinary people of varied ages sharing bread, singing and smiling, a small central cluster of joined hands; open golden space beyond, no national flags.","rationale":"低弦の小さな主題が合唱へ広がる過程と、シラーの歓喜・友愛の詩から、共に席につく人々を選んだ。ルノワールの人間同士の温度を感じる集団像で描く。","source":"songs/beethoven-9.md","evidence":{"summary":"ベートーヴェン最後の交響曲の終楽章。シラーの詩に曲を付けた歓喜の主題が、低弦の静かな入りから独唱と合唱を伴う大合唱へ広がる。","nameOrigin":"ベートーヴェン自身は表題を付けていない。第4楽章に合唱が入ることから「合唱付き」と通称され、日本では「第九（だいく）」とも呼ばれる。歌詞はシラーの詩『歓喜に寄す』から約3分の1を抜粋し、一部を作曲者が編集したもの。","features":"ソナタ形式の第1楽章、スケルツォの第2楽章、変奏曲の第3楽章のあと、第4楽章に声楽を導入した点が当時としては大胆。第3・第4楽章が続けて変奏曲である点も異例。トライアングル、シンバル、バスドラムなど、他のベートーヴェンの交響曲にない打楽器も使われる。","structure":[["第4楽章の冒頭（Presto）","不協和音の激しい序奏で始まり、低弦のレチタティーヴォ風の呼びかけと、第1〜3楽章の主題の回想・否定が続く。"],["歓喜の主題の提示","低弦のユニゾンで静かに歓喜の主題が現れ、徐々に楽器が加わって大きく展開する。"],["バリトン独唱「おお友よ、このような音ではない」","作曲者自身が付け加えた言葉で声楽が登場し、続いて合唱と四重唱へ進む。"],["行進曲風の変奏と二重フーガ","トルコ風の行進曲を経て、二つの主題を組み合わせるクライマックスの合唱フーガへ。"],["コーダ（Prestissimo）","合唱と独唱、管弦楽が一気に加速し、祝祭的に全曲を締めくくる。"]]},"asset":"assets/impressive/beethoven-9.webp","focus":[0.5,0.48],"motion":"light","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"vivaldi-spring","title":"ヴァイオリン協奏曲集「四季」より 春 第1楽章 (協奏曲 ホ長調 作品8-1 RV269)","artist":"monet","subject":"A brilliant spring meadow with newly wet blossoms, birds visible as a few real distant shapes, a passing dark shower cloud above a returning shaft of sunlight.","rationale":"ソネットの春の到来、鳥、嵐と、主題が戻るリトルネロに基づく。モネの天候で変わる色面を用い、晴れ一色ではない春の時間を描く。","source":"songs/vivaldi-spring.md","evidence":{"summary":"ヴィヴァルディ「四季」の冒頭を飾る「春」の第1楽章。ソネットに基づき小鳥や嵐を描く明るいホ長調の協奏曲で、独奏ヴァイオリンの技巧と軽快な主題が魅力。","nameOrigin":"La primavera（春）。各曲に付されたソネットが季節の情景を描くことから標題音楽的な「四季」と呼ばれる","features":"ソネットと結びついた描写的な音楽で、冒頭のリトルネロ主題が繰り返し戻る協奏曲形式の中に、鳥・嵐などの情景が独奏ヴァイオリンの装飾的パッセージで挿入される。","structure":[["第1楽章 Allegro（ホ長調）","春の到来を告げる明るい主題と、鳥のさえずり・嵐を表すとされる挿入部"],["第2楽章 Largo e pianissimo sempre（嬰ハ短調）","静かな緩徐楽章。犬の吠え声の指示がある"],["第3楽章 Allegro","舞曲風の終楽章（今回は詳細未確認）"]]},"asset":"assets/impressive/vivaldi-spring.webp","focus":[0.5,0.48],"motion":"foliage","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"largo-new-world","title":"交響曲第9番 ホ短調「新世界より」第2楽章 ラルゴ（「家路」）","artist":"twachtman","subject":"A narrow footpath across a silver-grey field toward one distant lit farmhouse at dusk, low hills, spare bare trees and a small warm window in otherwise cool ivory and jade.","rationale":"息の長いコーラングレと郷愁、後の家路の歌詞を、遠い家の灯へ続く道に重ねる。米国印象派トワクトマンの抑えた色調と薄い絵具の層で静かな距離を描く。","source":"songs/largo-new-world.md","evidence":{"summary":"コーラングレが歌う変ニ長調の主題で知られる『新世界より』の緩徐楽章。のち英語詞『Goin' Home』や堀内敬三の『家路』となり、日本でも広く愛される。","nameOrigin":"「新世界」はアメリカを指す。第2楽章の旋律は、ドヴォルザークの弟子（資料により同僚とも）W・A・フィッシャーが1922年に歌詞を付けて歌曲「Goin' Home」とした。日本では1946年に堀内敬三が日本語詞を付けた「家路（遠き山に日は落ちて）」として親しまれる。宮沢賢治が1924年夏までに自作の詩を同じ主題に付けて歌っていた（『種山ヶ原』）との記述もある。","features":"コーラングレの独奏による息の長い旋律。五音音階に近い音の運びが日本人に親しみやすい、との指摘もある（資料による説明）。ドヴォルザークは、先住民音楽やアフリカ系アメリカ人の霊歌の特徴を取り入れたが、旋律をそのまま引用したわけではないと述べている。","structure":[["導入","管楽器による和音の進行。研究者は「むかしむかし」という語りの定型を表すと解釈する"],["第1部（主題）","弱音器付きの弦の上で、コーラングレが変ニ長調の主題を独奏する"],["中間部","嬰ハ短調で郷愁と寂しさを帯び、低弦のピツィカートの上で葬送行進風になる。続いてスケルツォ風の部分に、この楽章の主題と第1楽章の主題が現れる"],["結び","主題と導入の和音がそっと戻って静かに閉じる"]]},"asset":"assets/impressive/largo-new-world.webp","focus":[0.5,0.48],"motion":"sky","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"bolero","title":"ボレロ","artist":"degas","subject":"A single Spanish dancer viewed from above on a circular wooden tavern platform, red skirt modeled by dry pastel, surrounding musicians suggested in dark edges; repeated floor arcs and tense still center.","rationale":"同じ三拍子と二つの旋律を音色と音量で積み上げるバレエ曲から、一人の舞台を囲む空間を選んだ。ドガの鋭い素描とパステルの重なりで、反復と圧力を表す。","source":"songs/bolero.md","evidence":{"summary":"小太鼓の同じリズムに乗せ、2つの旋律を楽器を替えて繰り返し、約15分かけて音量を積み上げるラヴェルの代表作。1928年にバレエ曲として初演された。","nameOrigin":"スペインの舞曲「ボレロ」にちなむ。楽譜の速度標語が「Tempo di Bolero, moderato assai（ボレロの速度で、非常に中庸に）」。","features":"旋律・リズム・和声がほぼ変わらず、音色（楽器の組み合わせ）と音量だけが変化する。サクソフォンはソプラニーノ（F管）を指定しているが、F管のソプラニーノは実在せず、初演時から変ロ管ソプラノで演奏されてきたと伝えられる。","structure":[["リズム","小太鼓が3拍子のリズムを冒頭から最後まで刻み続ける"],["2つの旋律","どちらも18小節。第1旋律は全音階的、第2旋律はシンコペーションや下降音を含みフリギア旋法に近い。交互に8回ずつ反復し、頂点で第1旋律がもう一度（9回目）現れる"],["楽器の受け渡し","フルート、クラリネット、ファゴット、E♭クラリネット、オーボエ・ダモーレ、トランペット、サクソフォン、ホルン、トロンボーン…と旋律の担当が移り、次第に弦や大勢の楽器が加わる"],["中盤以降の重ね","ホルンの旋律にチェレスタやピッコロがG・Eなど別の調で重なり、倍音を補強するように響きが輝きを増す"],["結尾","練習番号18で突然ホ長調に転じ、8小節ほどでハ長調に戻る。最後の6小節でバスドラム・シンバル・タムタムが初めて入り、トロンボーンのグリッサンドを伴って閉じる"]]},"asset":"assets/impressive/bolero.webp","focus":[0.5,0.48],"motion":"light","medium":"pastel","focusPortrait":[0.5,0.48]},{"id":"pomp-circumstance-1","title":"行進曲「威風堂々」第1番","artist":"hassam","subject":"A British civic promenade in strong daylight with processional crowds, vertical poles and many loosely painted red-blue-gold cloths, white stone and flickering cobalt shadows.","rationale":"静かなトリオが全管弦楽へ拡大する祝祭性を、個々の歩みから広がる街の行列へ読む。ハッサムの都市の垂直リズムと小さな強い筆触を選んだ。","source":"songs/pomp-circumstance-1.md","evidence":{"summary":"エルガーが1901年に書いた行進曲。弱音で始まる『希望と栄光の国』のトリオが全管弦楽で堂々と再現され、英国の祝祭や各国の卒業式で親しまれる。","nameOrigin":"題名の『Pomp and Circumstance（威風堂々）』はシェイクスピア『オセロ』第3幕第3場の台詞から。第1番の楽譜には、ド・タブリー卿の詩『栄光の行進』の一節も全曲集のモットーとして添えられた（英Wikipedia）。","features":"弱音で始まる『希望と栄光の国』のトリオと、全管弦楽・オルガン・ハープを動員した再現との対比。編成にはバス・クラリネット、コントラファゴット、コルネット、オルガン、ハープ2台などが含まれる。","structure":[["序奏と行進曲主部","Allegro con molto fuoco（活気に満ちて火のように）の序奏から、低音が旋律とぶつかる力強い主題が現れる。主部は反復される。"],["ブリッジ","金管の和音と木管・弦の保持音のあと、トランペットとトロンボーンのファンファーレが冒頭の主題を呼び戻す。"],["トリオ","ト長調で、第1ヴァイオリン、ホルン4本、クラリネットが弱音で提示。続いて2台のハープを含む全管弦楽で反復される。"],["再現と結び","行進曲主部が戻り、トリオは主調ニ長調でオルガンも加わって堂々と再現。曲は大旋律ではなく、冒頭の活発な主題の回想で閉じられる。"]]},"asset":"assets/impressive/pomp-circumstance-1.webp","focus":[0.5,0.48],"motion":"foliage","medium":"painting","focusPortrait":[0.5,0.48],"protect":[0.3,0.17,0.4,0.66]},{"id":"eine-kleine","title":"アイネ・クライネ・ナハトムジーク K.525 第1楽章","artist":"renoir","subject":"A small string ensemble giving a serenade on a lamplit garden terrace, four or five players forming a compact intimate central group, warm instruments against indigo night.","rationale":"小編成の弦のための夜の音楽という性格と、上昇する明快な主題から、実際の身近なセレナードを選んだ。ルノワールの暖かな人物と楽器の量感で描く。","source":"songs/eine-kleine.md","evidence":{"summary":"モーツァルトが1787年に書いた弦楽のためのセレナード。上昇音型で始まる明快なソナタ形式の第1楽章で、最も親しまれたクラシック曲の一つ。","nameOrigin":"モーツァルト自身の自作品目録に「Eine kleine Nacht-Musick」と記されたことから。ドイツ語の意味は「小さな夜の音楽」で、特別な曲名として付けたのではなく、小さなセレナードの完成を記録しただけとの見方がある。","features":"2つのヴァイオリン、ヴィオラ、チェロ、コントラバスのための作品だが、弦楽合奏で演奏されることも多い。大編成の曲ではなく、短い楽章の中に主題の明快さが凝縮されている。Britannicaは、最もよく演奏され、象徴的な古典曲のひとつと評している。","structure":[["提示部","上昇する「マンハイム・ロケット」の主題で始まる。第2主題は優美で、属調のニ長調。提示部は繰り返される。"],["展開部","ニ長調で始まり、ニ短調やハ長調に触れたのち、ト長調に戻る。"],["再現部","ト長調に戻って主題が再現し、楽章を結ぶ。"]]},"asset":"assets/impressive/eine-kleine.webp","focus":[0.5,0.48],"motion":"light","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"pictures","title":"ムソルグスキー作曲（ラヴェル編曲）組曲「展覧会の絵」","artist":"degas","subject":"A lone visitor seen from behind walking through a picture gallery, paintings of several different sizes on the walls, a grand arch glimpsed beyond; daring diagonal floor and muted ochre-blue pastel.","rationale":"ハルトマンの遺作展を歩くプロムナードと、絵ごとの異なる世界を、鑑賞者の歩みとして描く。ドガの斜めの視点と確かな人物素描で見る行為を中心にする。","source":"songs/pictures.md","evidence":{"summary":"ムソルグスキーがハルトマンの遺作展を歩く姿を描いたピアノ組曲を、ラヴェルが色彩豊かな管弦楽に編んだ名作。プロムナードとキエフの大門が特に有名。","nameOrigin":"ハルトマンの遺作展の絵（水彩・素描）を音楽で描いたことから「展覧会の絵」","features":"プロムナードの主題が曲間に変化しながら戻り、終曲で壮大な頂点を迎える。ラヴェル版は多彩な管楽器、サクソフォン、チェレスタ、2台のハープなどを加えた大編成の管弦楽法。","structure":[["プロムナード","会場を歩く様子。不規則な拍子で歩みを表す"],["小人（グノームス）","くるみ割り人形のデザインとされるハルトマンのスケッチ"],["古城、テュイルリー、ブイドロ（牛車）など","各曲が特定の絵に対応。ただし多くの絵は失われている"],["カタコンベ〜死せる言葉による死者との対話","プロムナード主題が曲そのものの一部となる転換点"],["キエフの大門（ボガトゥイリの門）","変ホ長調。プロムナード主題が頂点を築く終曲"]]},"asset":"assets/impressive/pictures.webp","focus":[0.5,0.48],"motion":"light","medium":"pastel","focusPortrait":[0.5,0.48]},{"id":"le-cygne","title":"動物の謝肉祭 第13曲「白鳥」（チェロとピアノ版を中心に）","artist":"monet","subject":"One anatomically convincing white swan gliding on calm blue-green water, a long delicate wake and pale willow reflections; the neck and reflected body form the portrait-safe center.","rationale":"チェロの長い旋律と二台のピアノのさざ波から、白鳥とその下で絶えず動く反射を選んだ。モネの水平の筆触を用い、後世の瀕死のバレエ像をそのまま当てはめない。","source":"songs/le-cygne.md","evidence":{"summary":"動物の謝肉祭の中で唯一、作曲者が生前の公開を許した曲。チェロが水面を滑る白鳥のように静かに歌い、後にバレエ『瀕死の白鳥』でも知られた。","nameOrigin":"動物の謝肉祭の一曲として白鳥を描いたもの。「スワン・ソング（白鳥は死の間際に最も美しく歌う）」という古代ギリシャ以来の俗信に結びつけて、美の儚さを描いた作品と解釈されることがある。「瀕死の白鳥」の通称は、後にパヴロワのバレエ小品が付けられたことによる。","features":"チェロの長いレガート旋律を、ピアノのほぼ絶え間ない分散和音が支える。組曲中、風刺や引用の冗談がほぼない真摯な曲で、サン＝サーンスが生前に公開を許した唯一の楽章。チェロ以外にもヴィオラ、ダブルベース、テルミン、声楽（ヴォカリーズ）、ピアノ独奏編曲（ゴドフスキー、ジロティ）など多数の編曲がある。","structure":[["導入部","ピアノ2台が細かい分散和音（片方は16分音符のさざ波、もう片方は和音）で水面を描き、その上にチェロが入る"],["主旋律","ゆったりとしたチェロの歌が、水面を滑る白鳥を思わせる息の長い旋律線で続く（全28小節）"],["終結","静かに旋律が収まり、穏やかに終わる"]]},"asset":"assets/impressive/le-cygne.webp","focus":[0.5,0.48],"motion":"water","medium":"painting","focusPortrait":[0.6,0.48],"protect":[0.35,0.28,0.34,0.4]},{"id":"jupiter","title":"組曲「惑星」より 木星（快楽をもたらす者）","artist":"renoir","subject":"A lively outdoor harvest dance with a small central circle of ordinary people, the surrounding crowd opening into a broad sunlit meadow; joyous warm flesh and blue-gold light, no planet.","rationale":"占星術上の歓喜と、活発な舞曲から儀式的な大きい歌へ広がる内容に基づく。天体写真ではなく、人の輪の喜びをルノワールの集団像で描く。","source":"songs/jupiter.md","evidence":{"summary":"活気ある舞曲風の主部と、中間部の広い旋律の対比が魅力。中間部は英国の賛歌と平原綾香『Jupiter』の原曲にもなった、ホルスト『惑星』の代表楽章。","nameOrigin":"副題の「Bringer of Jollity」は占星術上の木星の性格づけに由来する。ホルストは「日常的な喜びと、宗教的・国家的な祝祭のより儀式的な喜び」を指すと説明した。日本語では「快楽」のほか「歓喜」などと訳される。中間部の旋律は1921年に詩「I Vow to Thee, My Country」の旋律に転用され、のち賛歌曲「サクステッド」の名で知られる。日本では2003年に平原綾香『Jupiter』（吉元由美作詞）の旋律にもなった。","features":"曲全体は活気に満ちた舞曲風の部分と、中間部の広い歌とのコントラストで成り立つ。中間部の旋律は終止が解決しないまま次へ進む点も特徴とされる。『惑星』は大編成（オルガン、チェレスタ、テナーチューバなどを含む）で書かれており、この楽章でもその音色の幅が生かされる。","structure":[["第1〜第3主題（Allegro giocoso）","ホルンの快活な第1主題で始まり、リズミカルな第2主題、舞曲風の素朴で明るい第3主題が続く"],["中間部（Andante maestoso）","弦とホルンが歌う厳かな第4主題。冒頭の半分の速さで3/4拍子、変ホ長調。この旋律が賛歌「我は汝に誓う、我が祖国よ」と平原綾香『Jupiter』の原曲となった"],["再現部","第1〜第3主題が再現し、第4主題がロ長調で戻る"],["結尾","全管弦楽による3連続フォルテ（fff）の一撃の和音で終わる"]]},"asset":"assets/impressive/jupiter.webp","focus":[0.5,0.48],"motion":"light","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"toccata-fugue-dm","title":"トッカータとフーガ ニ短調 BWV565","artist":"monet","subject":"The interior of a Gothic church at stormy late afternoon, dark organ pipes and four receding bands of arches dissolving into cold violet and ochre light; powerful material paint, no abstract neon.","rationale":"劇的なトッカータと四声のフーガを、縦のオルガンと奥へ重なる空間に重ねる。モネの聖堂を光と色の塊として捉える手法で、建築図にはしない。","source":"songs/toccata-fugue-dm.md","evidence":{"summary":"オルガン曲を代表する一曲で、劇的な冒頭と16分音符のフーガが続く。バッハ作とされてきたが、真作性には1981年以来異論もあり、結論は出ていない。","nameOrigin":"リンク写本の表題は伊語で「Toccata con Fuga」。同じニ短調の別作品（BWV538）が通称「ドリア調」と呼ばれて区別されていたが、1950年のBWV（バッハ作品目録）刊行以降は番号で呼ばれる。","features":"嵐を描いた標題音楽という見方がある一方、ディズニー『ファンタジア』では抽象的な絶対音楽として使われた。ヴァイオリン的な音型や、平行オクターヴ、単純な和声などが真作性をめぐる論点になっている。","structure":[["トッカータ","右手と足鍵盤の有名なオクターヴ重ねのモルデント音型で始まり、減七和音から跳ね上がる。冒頭はニ短調の主和音へ解決し、以降は即興風の音型が続く"],["フーガ","16分音符のみの主題による4声のフーガ。応答が下属調で行われる点が珍しく、足鍵盤が単独で主題を弾く箇所もある。終わり近くで変ロ長調の持続和音に至る"],["終結部（レチタティーヴォ）","わずか17小節の間に5度テンポが変わり、最後はMolto adagioでの短調の変格終止で閉じる"]]},"asset":"assets/impressive/toccata-fugue-dm.webp","focus":[0.5,0.48],"motion":"light","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"farandole","title":"ビゼー「アルルの女」第2組曲より ファランドール","artist":"pissarro","subject":"A chain of villagers dancing a farandole in a Provençal square, one central pair linking the curving chain, tambourine and sunlit ochre walls in a carefully structured rural scene.","rationale":"プロヴァンスの二つの旋律が対位的に重なることと民俗舞曲に基づく。ピサロの土地と生活を捉える小筆触で、音楽の連なりを人の鎖として描く。","source":"songs/farandole.md","evidence":{"summary":"ビゼー「アルルの女」第2組曲の終曲。プロヴァンスの行進曲と舞曲の旋律が重なり、タンブランが響く熱狂的なクライマックスへ駆け上がる。","nameOrigin":"ファランドールはプロヴァンス地方の舞曲の名。旋律「Danso dei Chivau-Frus（馬の踊り）」に由来","features":"プロヴァンス民謡の二つの旋律を対位的に重ね、フルート・ピッコロ・タンブランで舞曲の色彩を出し、大きな盛り上がりで曲を終える。","structure":[["第22曲Final（劇音楽）","『馬の踊り』の旋律を含む。第2組曲ではファランドールの一部になる"],["第23曲Entr'acte and Chorus","合唱が管弦楽に置き換えられファランドールに編入"],["ファランドール","短調の『3人の王の行列』と長調の『馬の踊り』が組み合わされ、クライマックスへ"]]},"asset":"assets/impressive/farandole.webp","focus":[0.5,0.48],"motion":"foliage","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"carmen-prelude","title":"歌劇「カルメン」前奏曲（第1幕への前奏曲）","artist":"degas","subject":"A scarlet theatre curtain pulled aside above a brilliant distant procession, one dark triangular stage-wing shadow crossing the warm floor; vivid rust, ochre and sharp blue-black pastel.","rationale":"闘牛士の祝祭的な入場から運命の動機へ変わる前奏曲を、明るい舞台と暗い袖の同居として描く。ドガの舞台照明と鋭い斜線を選んだ。","source":"songs/carmen-prelude.md","evidence":{"summary":"闘牛士の行進と歌の旋律が輝く幕開けのあと、運命の動機が弦のトレモロの上で不穏に響く。ビゼーが全曲の悲劇を先取りした前奏曲。","nameOrigin":"Prelude（前奏曲）は第1幕への導入曲。『カルメン』の題名は、メリメの小説およびその主人公の名による。","features":"オペラ全体を支配する運命の動機が、冒頭からすでに提示される点。第4幕の悲劇的な結末を予告する音の使い方が、前奏曲に含まれている（英Wikipedia）。","structure":[["祝祭的な主部（Allegro giocoso）","第4幕の闘牛士たちの入場の音楽と、第2幕『闘牛士の歌』の旋律が華やかに響く。組曲では『闘牛士』として独立して演奏される。"],["運命の動機","クラリネット、ファゴット、コルネット、チェロが、弦のトレモロの上で運命の動機を奏する。"],["結び","運命の動機が急激なクレッシェンドを伴って前奏曲を締めくくり、幕が開くと明るく陽気な空気に切り替わる。"]]},"asset":"assets/impressive/carmen-prelude.webp","focus":[0.5,0.48],"motion":"light","medium":"pastel","focusPortrait":[0.5,0.48]},{"id":"cavalleria-intermezzo","title":"歌劇「カヴァレリア・ルスティカーナ」間奏曲","artist":"pissarro","subject":"An entirely empty Sicilian village square at Easter morning, a closed central church door, white cloth at a small window and long still sunlit paving, no violence or melodramatic figures.","rationale":"復讐の誓いの直後、舞台が無人になる間奏曲という劇中の位置を優先した。ピサロの実在感のある村と静かな土色で、嵐の前の静けさを描く。","source":"songs/cavalleria-intermezzo.md","evidence":{"summary":"復讐の誓いの直後、無人の広場に流れるマスカーニの静かな間奏曲。弦の長い旋律が嵐の前の静けさを描き、映画『レイジング・ブル』でも知られる。","nameOrigin":"歌劇の題名 Cavalleria rusticana は『田舎の騎士道（農民の名誉）』の意（英Wikipedia）。Intermezzoは幕の間に置かれる間奏曲の意。","features":"ヴェリズモ（写実主義）の血なまぐさい筋立ての只中に置かれた、きわめて抒情的で静謐な間奏曲。歌劇の編成にはオルガン、ハープ2台、チューブラーベルなどが含まれる。","structure":[["位置づけ","歌劇の唯一の幕間。アルフィオがトゥリッドゥへの復讐を誓う場面の直後、舞台は無人のまま管弦楽だけが奏される。"],["素材","旋律は、歌劇冒頭の復活祭ミサで合唱が歌う『レジーナ・チェリ』の聖歌に基づくとされる（AllClassical解説）。"],["表情","嵐の前の静けさを作る穏やかな一曲。主旋律を弦が歌い、オルガンやハープが加わる編成が歌劇の指定にある。"]]},"asset":"assets/impressive/cavalleria-intermezzo.webp","focus":[0.5,0.48],"motion":"light","medium":"painting","focusPortrait":[0.57,0.48]},{"id":"barber-adagio","title":"弦楽のためのアダージョ 作品11","artist":"twachtman","subject":"A snow-edged stream under bare trees, a path rising slowly toward a pale ridge, a suspended silver-white sky with a single break in the cloud; almost monochrome matte scumbling.","rationale":"段を上る旋律、頂点の沈黙、解決しきらない終わりを、少しずつ上る道と途切れた光へ読む。トワクトマンの淡い層と抑えた輪郭で追悼の静けさを作る。","source":"songs/barber-adagio.md","evidence":{"summary":"弦楽四重奏曲の緩徐楽章を弦楽合奏に編曲した、静かに高まっていく名曲。1938年にトスカニーニが初演し、追悼の場でも多く演奏されてきた。","nameOrigin":"曲名は速度標語の「アダージョ（ゆるやかに）」に由来し、作曲者名をつけて「バーバーのアダージョ」とも呼ばれる。1967年には同じ音楽に典礼文を付した合唱曲『アニュス・デイ』も作られた。","features":"アーチ形の構成と、規則的な拍子に5/2・6/2・3/2の小節を挟んで脈拍を微妙に揺らす手法が特徴。和声は素朴な三和音が基調で、聖歌のような旋律を持つ。演奏時間は多くの録音で8分前後。","structure":[["冒頭","第1ヴァイオリンが静かな変ロ音で始まり、2拍遅れて低弦が入る。段をのぼるような旋律が始まる"],["上昇部","旋律が重なり合いながら、ルネサンス風のポリフォニーを思わせる響きで高まっていく"],["クライマックス","4つの力強い和音と長いフェルマータの沈黙"],["回帰と終結","冒頭の主題が戻り、解決しない属和音で消えるように終わる"]]},"asset":"assets/impressive/barber-adagio.webp","focus":[0.5,0.48],"motion":"sky","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"nessun-dorma","title":"歌劇「トゥーランドット」より 誰も寝てはならぬ","artist":"monet","subject":"A dark Chinese palace garden before dawn, still water and a distant plausible tiled pavilion; one narrow warm band begins beyond the central trees while stars fade, no fantasy architecture.","rationale":"夜から夜明けの勝利へ向かうカラフの詞に基づき、眠れない庭と消えゆく星を描く。モネの刻々変わる光の手法で、暗部から開く朝を主役にする。","source":"songs/nessun-dorma.md","evidence":{"summary":"プッチーニ最後の歌劇『トゥーランドット』第3幕で、王子カラフが夜明けの勝利を確信して歌う名アリア。静から高揚へ進む旋律が魅力です。","nameOrigin":"歌い出しのイタリア語 Nessun dorma（誰も寝てはならぬ）に由来。日本でもこの和訳が通称。","features":"最後の「勝利」を意味する語で高音が長く保たれる演奏慣習があるが、プッチーニの楽譜に明示された指示ではないと英Wikipediaは記す。","structure":[["冒頭","触れ役の声を受け、姫も眠れぬ夜を過ごしているだろうと語りかける"],["中間部","自分の名は胸の内に秘めたまま、夜明けに口づけで告げようと確信を示す"],["女声合唱","遠くから名は誰にも分からず、我々は死ぬのだと嘆く声が重なる"],["結び","夜よ去れ、星よ沈めと呼びかけ、夜明けの勝利を高らかに宣言する"]]},"asset":"assets/impressive/nessun-dorma.webp","focus":[0.5,0.48],"motion":"sky","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"brindisi","title":"歌劇「椿姫」より 乾杯の歌","artist":"renoir","subject":"An intimate Paris salon party with a central man and woman raising real crystal glasses, other guests softly grouped behind them, warm flesh, rose and amber light against blue shadows.","rationale":"二人の独唱から掛け合いと全員の合唱へ広がる乾杯の場面を描く。ルノワールの身体とグラスに届く光で、三拍子の社交の温度を出す。","source":"songs/brindisi.md","evidence":{"summary":"ヴェルディ『椿姫』第1幕の夜会で歌われる、アルフレードとヴィオレッタの華やかな乾杯の二重唱。3拍子の軽快な旋律で親しまれています。","nameOrigin":"冒頭の歌詞 Libiamo ne' lieti calici（楽しい杯で飲もう）より。brindisi は乾杯・祝杯の歌を指す語。","features":"3拍子の軽快なワルツ風リズムで、独唱、掛け合い、合唱へと盛り上がっていく構成。","structure":[["アルフレードの独唱","乾杯を呼びかけ、愛と快楽を讃える"],["合唱","全員がアルフレードの旋律を受けて繰り返す"],["ヴィオレッタの独唱","人生の喜びは束の間と応じて、楽しもうと歌う"],["全員の合唱","二人の掛け合いを挟み、夜会の高揚で締めくくる"]]},"asset":"assets/impressive/brindisi.webp","focus":[0.5,0.48],"motion":"light","medium":"painting","focusPortrait":[0.49,0.48]},{"id":"habanera","title":"歌劇「カルメン」より ハバネラ（恋は野の鳥）","artist":"degas","subject":"A confident adult woman in a tasteful long dark skirt and red shawl turning away from admirers at a tavern doorway, a small open window above; angular pose and coarse rust-green pastel.","rationale":"恋は誰にも従わない野の鳥だというカルメン自身の詞から、自由な方向へ身体を向ける人を選ぶ。ドガの強い輪郭と重心の観察で、甘い花の象徴へ置き換えない。","source":"songs/habanera.md","evidence":{"summary":"ビゼー『カルメン』第1幕、カルメンが登場して歌う挑発的なアリア。ハバネラのリズムに乗せ、恋は気まぐれな野の鳥だと歌います。","nameOrigin":"ハバネラは『ハバナの（音楽・舞曲）』の意。原題は歌い出しの L'amour est un oiseau rebelle（恋は反抗的な鳥）。","features":"ニ音の持続低音が全体を通して保たれ、調は途中で転調せず短調から長調に変わる。低音域のフルートとハバネラのリズムが独特の気配を作る（英Wikipedia）。","structure":[["レシタティフ","いつあなたを愛するかと問われ、たぶん永遠にない、明日かも、と軽くかわす"],["ハバネラ主部","恋は誰にも飼いならせない野の鳥だと歌う"],["リフレイン（合唱を交えて）","恋は掟を知らない、私を愛さないならこちらが愛する、気をつけなさいと迫る"],["後半の節","捕らえたつもりの鳥は逃げ、忘れた頃に戻ってくるとたたみかける"]]},"asset":"assets/impressive/habanera.webp","focus":[0.5,0.48],"motion":"light","medium":"pastel","focusPortrait":[0.5,0.48]},{"id":"orpheus-overture","title":"喜歌劇「天国と地獄」序曲（カンカンを含む）","artist":"degas","subject":"A candid cabaret stage with three adult cancan dancers in long ruffled skirts caught at different moments of a lively turn, visible stage boards, dark musicians and acid ochre light, plausible anatomy.","rationale":"ビンダーがつないだ序曲の終盤、地獄のギャロップと後のカンカン文化を題材にする。ドガの素描と乾いたパステルで速度の違う身振りを組み合わせる。","source":"songs/orpheus-overture.md","evidence":{"summary":"オッフェンバックの喜歌劇の旋律をウィーンでビンダーがつないだ序曲。終盤の「地獄のギャロップ」は、カンカン踊りの定番曲として世界中で知られる。","nameOrigin":"原題Orphée aux enfersは「地獄のオルフェ（オルフェウス）」の意。「Galop infernal」は「地獄の（猛烈な）ギャロップ」という意味の曲名。1890年代にパリのムーラン・ルージュやフォリー・ベルジェールがこの曲をカンカン踊りの伴奏に採用し、以後「カンカン」の名で親しまれた。日本語題「天国と地獄」の由来は未確認。","features":"オッフェンバックは「ギャロップ・アンフェルナル」のような速い曲で、同じ調を長く保ち楽器編成もほぼ一定にする簡潔な書き方をしている、と研究者が指摘している。原曲は、のちの上品なカンカンより遥かに自然発生的で乱痴気騒ぎ的だったとされる（ケック氏は現代のレイヴになぞらえている）。","structure":[["序盤（ゆったりした導入）","劇中の旋律を使った静かな部分から始まる（細部の曲名は未確認）"],["中盤（劇中旋律のつなぎ）","ウィーン版序曲はオルフェのヴァイオリン独奏を前面に出し、劇中の旋律をメドレー風に並べる"],["終盤（ギャロップ）","劇の第2幕（1874年版では第4幕）の終幕場面に由来する「地獄のギャロップ」。神々が大騒ぎで踊る場面の曲で、序曲を締めくくる"]]},"asset":"assets/impressive/orpheus-overture.webp","focus":[0.5,0.48],"motion":"light","medium":"pastel","focusPortrait":[0.5,0.48]},{"id":"william-tell-overture","title":"歌劇「ウィリアム・テル」序曲（終曲：スイス兵の行進）","artist":"degas","subject":"A few realistically drawn horses and riders galloping along a Swiss alpine road after a storm, one central horse seen in three-quarter side view, streaked grass and distant calm mountain air.","rationale":"今回の音源が序曲終曲のスイス兵の行進であることとギャロップの速さを優先する。ドガの馬の観察と斜めの構図で疾走を描き、テレビの西部劇へは移さない。","source":"songs/william-tell-overture.md","evidence":{"summary":"ロッシーニ最後のオペラの序曲。夜明けと嵐と牧歌を経て、トランペットの合図で一気に駆け出す終曲は、『ローン・レンジャー』などで世界的に知られる。","nameOrigin":"英語名の終曲「March of the Swiss Soldiers」は「スイス兵の行進」の意。実際は行進曲というより「ギャロップ」で、馬が駆けるイメージから米国ラジオ・テレビ番組『ローン・レンジャー』の主題曲として定着した。","features":"ロッシーニの曲を象徴するクレッシェンドは本稿の調査では未確認のため言及を控える。確認できた点は、前奏がチェロ5本というユニークな編成であること、終曲はトランペットで告げられる「ギャロップ」で、馬の疾走や救援のイメージとして広く使われること。","structure":[["第1部 前奏（夜明け）","ホ短調で始まる約3分。独奏チェロ5本をコントラバスが支える。遠雷を思わせるティンパニが嵐を予告する"],["第2部 嵐","ホ短調。全管弦楽が加わる約3分の激しい部分。ピッコロ、フルート、オーボエ、クラリネット、ファゴットの短い応答、続いて金管と大太鼓が嵐を爆発させ、徐々に静まる"],["第3部 牧歌（ランツ・デ・ヴァッシュ）","ト長調。嵐の後の静けさ。イングリッシュ・ホルンがスイスの牛追い歌を吹き、フルートと掛け合う"],["第4部 終曲（スイス兵の行進）","ホ長調。トランペットのファンファーレに始まり、全管弦楽で駆け抜けるギャロップ。約3分"]]},"asset":"assets/impressive/william-tell-overture.webp","focus":[0.5,0.48],"motion":"foliage","medium":"pastel","focusPortrait":[0.56,0.48],"protect":[0.3,0.17,0.4,0.66]},{"id":"queen-of-night","title":"歌劇「魔笛」より 夜の女王のアリア「復讐の心は地獄のように我が胸に燃え」","artist":"degas","subject":"A stern adult opera singer in a modest dark-blue theatrical gown on a shadowy stage, one hand raised sharply, a distant pale vertical light and angular silver-blue fabric, no knife or galaxy.","rationale":"娘への怒りと高いスタッカートの跳躍を、歌手の鋭い重心と上がる手へ結びつける。ドガの炭の素描と強い色紙で、単なる美しい星空にしない。","source":"songs/queen-of-night.md","evidence":{"summary":"復讐に燃える夜の女王が娘にナイフを握らせる、『魔笛』第2幕の怒りのアリア。高音のスタッカートと変ロ音の叫びが、ソプラノの技巧の頂点として知られる。","nameOrigin":"歌い出しの「Der Hölle Rache kocht in meinem Herzen」（地獄の復讐が私の胸に煮えたぎる）にちなむ通称。夜の女王には前半に別のアリア「おののくな、わが息子よ」があるため、こちらは「夜の女王の第2のアリア」とも呼ばれる。","features":"ある研究者は、頂点の「聞け」でニ・ヘと上がった後に、予想されるイ音（主和音の完成）ではなく変ロ音へ進むモーツァルトの「名人芸」を称賛している。管弦楽には全ヴァイオリンがG線の高音域をユニゾンで弾く瞬間がある。","structure":[["怒りの導入","短調の力強い管弦楽とともに、女王が復讐の怒りを歌い始める"],["コロラトゥーラの技巧","高音のスタッカートを含む華やかな上行・下行パッセージ（最高音F6）が続く"],["最後の呪い","「ヒョルト（聞け）」が3回繰り返され、ニ、ヘと来て予想された（イ）ではなく変ロ音に達する。ナポリの和音を伴い、アリアの頂点となる"]]},"asset":"assets/impressive/queen-of-night.webp","focus":[0.5,0.48],"motion":"light","medium":"pastel","focusPortrait":[0.56,0.48]},{"id":"toreador","title":"歌劇「カルメン」より 闘牛士の歌（諸君の乾杯を受けよう）","artist":"degas","subject":"A baritone-like adult man in a dark embroidered jacket returning a toast in a tavern, a few listeners forming a chorus behind, red cloth and amber light with dark diagonal shadows.","rationale":"実際には第2幕の酒場で歌われるクプレと合唱の場面を選んだ。ドガの舞台と人物の観察で、短調の語りと長調のリフレインの対比を光と集団で描く。","source":"songs/toreador.md","evidence":{"summary":"オペラ『カルメン』第2幕で闘牛士エスカミーリョが歌う有名なクプレ。闘牛場の熱狂と愛を歌い、合唱が加わるリフレインの高揚で知られる。","nameOrigin":"フランス語の冒頭句「Votre toast, je peux vous le rendre」（あなたの乾杯にお返ししよう）に由来。英語圏では『Toreador Song』『Toreador March』の通称で知られ、日本では「闘牛士の歌」と呼ばれる。","features":"バス・バリトンのための曲で、音域は B♭2〜F4、よく使われる音域（テッシトゥーラ）は C3〜E♭4。短調のクプレと長調のリフレインが対照をなし、合唱が加わると一気に祝祭的な性格に変わる。","structure":[["管弦楽の導入","きびきびと華やかな主題。ハバネラと同じく半音階的に下降する動きで作られている。"],["第1クプレ","闘牛場の祭りの熱気と、観衆が熱狂する様子を歌う。"],["リフレイン（合唱）","「闘牛士よ、構えよ」と呼びかけ、愛が待っていると歌う。カルメンたちと合唱が加わって反復される。"],["第2クプレ","牛が飛び出す緊迫の瞬間を描写し、勇気を称える。"],["終結のリフレイン","合唱とともに高揚して閉じる。"]]},"asset":"assets/impressive/toreador.webp","focus":[0.5,0.48],"motion":"light","medium":"pastel","focusPortrait":[0.5,0.48]},{"id":"figaro-letter-duet","title":"歌劇「フィガロの結婚」より 手紙の二重唱（そよ風によせて）","artist":"morisot","subject":"Two fully clothed women in simple eighteenth-century dresses at a small writing table near an open garden window, one dictating softly and one writing on blank paper, a light curtain above their close hands.","rationale":"伯爵夫人の口述をスザンナが書き取る劇中の動作と二声の絡みをそのまま題材にする。モリゾの女性の私的な空間と素早い白い筆触で、そよ風と策略の親密さを描く。","source":"songs/figaro-letter-duet.md","evidence":{"summary":"『フィガロの結婚』第3幕で、伯爵夫人とスザンナが偽の恋文を書く二重唱。『ショーシャンクの空に』での使用で広く知られる。","nameOrigin":"イタリア語の冒頭句「Sull'aria... Che soave zeffiretto」（そよ風に乗せて…なんと優しい西風よ）に由来。劇中で手紙を書く場面であることから「手紙の二重唱」と呼ばれる。","features":"2人のソプラノ（伯爵夫人とスザンナ）による短い二重唱。穏やかな旋律が、策略を進める場面でもあるという二重性を持つ。","structure":[["導入","伯爵夫人が口述し、スザンナが書き取る形で始まる。"],["手紙の口述","伯爵を夜の庭に誘う文面を二人で書き進める。"],["反復と終結","二人の声が絡み合い、手紙を仕上げる。"]]},"asset":"assets/impressive/figaro-letter-duet.webp","focus":[0.5,0.48],"motion":"light","medium":"painting","focusPortrait":[0.55,0.48]},{"id":"flower-duet","title":"歌劇「ラクメ」より 花の二重唱","artist":"monet","subject":"Two small fully clothed Indian women beside a narrow boat under a real jasmine canopy by a river, white blossoms and lotus leaves form interleaving reflected color, no generic bouquet close-up.","rationale":"ラクメとマリカが川辺で花摘みと舟遊びに向かう場面、三度と六度、6/8の揺れに基づく。モネの水と葉の重なりで二声を包み、花の造形を図形化しない。","source":"songs/flower-duet.md","evidence":{"summary":"オペラ『ラクメ』第1幕、ラクメと侍女マリカが川辺で花を摘みに向かう場面の二重唱。英国航空のCMでも知られる。","nameOrigin":"冒頭句「Dôme épais le jasmin」（茂るジャスミンの天蓋）に由来し、英語圏では『Flower Duet』と呼ばれる。なお題名の「ラクメ」は、サンスクリットの女神ラクシュミーのフランス語形とされる。","features":"ソプラノとメゾソプラノが三度・六度で重なる。6/8拍子の舟歌風のゆれる動きが、川面の揺れを思わせる。","structure":[["導入の対話","ラクメがマリカを誘い、マリカが主人の心を読みたいと応じる。"],["主部「Dôme épais le jasmin」","二人が三度の歌い交わしで、川辺の花々と舟遊びを描く。"],["中間部（ト長調）","ラクメが父への不安を語り、マリカが神の加護を願って蓮を摘みに行こうと誘う。"],["主部の再現","冒頭の旋律に戻り、二声が寄り添って終わる。"]]},"asset":"assets/impressive/flower-duet.webp","focus":[0.5,0.48],"motion":"water","medium":"painting","focusPortrait":[0.52,0.48]},{"id":"o-mio-babbino","title":"私のお父さん（歌劇「ジャンニ・スキッキ」より）","artist":"morisot","subject":"A young adult woman quietly appealing to her father on a Florentine balcony above a glimpse of the Arno, believable expressive hands, pale cloth and blue-green window shadow.","rationale":"ラウレッタが父へ結婚の許しを乞う短いアリアの内容を優先する。モリゾの親密な人物と軽い余白で、喜劇の中の切実な一瞬を描く。","source":"songs/o-mio-babbino.md","evidence":{"summary":"プッチーニの喜歌劇でラウレッタが父に結婚の許しを乞うアリア。わずか32小節の短さながら、甘く切実な旋律で愛され、映画やコンサートでも親しまれている。","nameOrigin":"歌い出しのイタリア語の句「O mio babbino caro」に由来する。意味は「ああ、愛しいお父さん」（babbinoは「パパ」にあたる親しみのある呼び方）。","features":"全32小節と非常に短く、変イ長調・8分の6拍子の流れるような旋律で歌われる。喜劇の中で唯一といえる抒情的なアリアで、素朴さと切実さの対比が魅力。","structure":[["導入と主部","ラウレッタが父に呼びかけ、恋人への思いを訴える柔らかな旋律が中心"],["中間部","結婚を許してほしいという願いが高まり、感情が盛り上がる"],["結び","父への最後の懇願として、静かな余韻のなかで締めくくる"]]},"asset":"assets/impressive/o-mio-babbino.webp","focus":[0.5,0.48],"motion":"light","medium":"painting","focusPortrait":[0.51,0.48]},{"id":"lascia-ch-io-pianga","title":"私を泣かせてください（歌劇「リナルド」より）","artist":"morisot","subject":"A fully clothed woman alone beside a high garden wall, a closed gate behind and a small open patch of sky, a few thorny stems and unoccupied pale space, sober soft charcoal-white-green gestures.","rationale":"囚われのアルミレーナが悲しみと自由を願う詞と重いサラバンドから、閉じられた庭と見える空を選ぶ。モリゾの描き残す輪郭で、嘆きを過度な劇画にしない。","source":"songs/lascia-ch-io-pianga.md","evidence":{"summary":"ヘンデルが1711年の歌劇「リナルド」で、囚われのアルミレーナの嘆きとして歌わせたアリア。過去の自作を転用した旋律が、悲しみと自由への願いを静かに歌う。","nameOrigin":"歌い出しのイタリア語「Lascia ch'io pianga」に由来し、意味は「私に泣かせてください」。元の旋律が使われた1707年のアリアは「Lascia la spina, cogli la rosa」（棘を捨て、バラを摘め）という別の詞だった。","features":"サラバンドの重く落ち着いた3拍子と、長い音符で紡がれる旋律が特徴。1つの旋律が器楽曲、オラトリオ、歌劇へと姿を変えて使い回された点もバロック期ならでは。","structure":[["導入（約8小節）","現代の版では、歌の前に器楽による導入が置かれる"],["前半","ヘ長調のゆったりしたサラバンド風のリズムで、運命を嘆き自由を求める歌"],["後半","同じ旋律を繰り返し、憐れみを願う結びへ向かう"]]},"asset":"assets/impressive/lascia-ch-io-pianga.webp","focus":[0.5,0.48],"motion":"light","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"rojo-no-tsuki","title":"荒城の月","artist":"monet","subject":"A ruined Japanese stone castle terrace at night, low broken masonry and real pine branches, small vines and a veiled moon beyond; faint remnants of an empty festive terrace, no intact fantasy castle.","rationale":"詩の春の宴・秋の陣営と、変わらない月が見る栄枯盛衰に基づく。モネのジャポニスムに通じる平面の重なりと光で、荒れた石と続く自然を描く。","source":"songs/rojo-no-tsuki.md","evidence":{"summary":"土井晩翠の詩に滝廉太郎が曲を付けた1901年の唱歌。栄枯盛衰を映す荒城の月を歌い、山田耕筰の編曲版とともに国内外で親しまれている。","nameOrigin":"土井晩翠の詩の原題『荒城月』を改めて『荒城の月』とした。荒れた城（荒城）と夜の月を詠む題。","features":"七五調の詩と西洋風の短調旋律を結びつけた作品。旋律は短音階第4音が上がる部分（原曲）を含み、橋本国彦は欧州に紹介するなら山田版が適すると語ったとされる（原曲の音型がジプシー音階やハンガリー民謡を連想させるため）。山田版は旋律の半音下げとピアノ伴奏の追加で、歌曲としての性格を強めた。","structure":[["第1節（春）","高楼での花見の宴と、かつての栄光はどこへ行ったかという問い。"],["第2節（秋）","陣営の霜と雁、剣を照らした往時の光はいまいずこ、という問い。"],["第3節","いま荒城の夜半の月は、誰のために変わらぬ光を放つのか。垣に残るのは蔓草、松に吹くのは風の音のみ。"],["第4節","天上の月は変わらないが、栄枯は移ろう世の姿をいまも映し続ける。"]]},"asset":"assets/impressive/rojo-no-tsuki.webp","focus":[0.5,0.48],"motion":"foliage","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"heidenroslein","title":"野ばら","artist":"pissarro","subject":"One real wild briar rose branch in a rough meadow, irregular five-petalled red blossoms, serrated leaves and conspicuous thorns, a small bent stem at the edge, dense earthy green touches.","rationale":"同じ旋律で三節を歌う簡潔さと、薔薇の警告・抵抗を含むゲーテの詩を読む。ピサロの植物と土地の観察で、可愛らしい花だけに内容を縮めず棘を残す。","source":"songs/heidenroslein.md","evidence":{"summary":"ゲーテの詩に付けた1815年の有節歌曲。3節が同じ旋律で歌われる素朴な作品で、ウェルナー版と並んで『野ばら』の名で親しまれる。","nameOrigin":"ゲーテの詩の題『Heidenröslein』（荒野＝Heideに咲く野ばら）。-nは連結音。『Heideröslein』とも書かれる（ドイツ語版Wikipedia）。","features":"3節が同一の旋律と伴奏で歌われる有節歌曲。各節の終わり2行は詩の側で繰り返される。声楽曲として簡潔で、民謡風の親しみやすさが特徴。ヴェルナー版（1829）の素朴な旋律は19世紀の歌集を通じて広まり、日本でもこの曲が『野ばら』として歌われてきた。","structure":[["第1節","少年が朝の露のように若い薔薇を見つけ、駆け寄って見とれる。"],["第2節","少年が摘むと言い、薔薇は棘で刺して自分を忘れさせないと警告する。"],["第3節","少年は結局摘み、薔薇は刺して抵抗するが、嘆いても無駄でそれに耐えるしかない。"],["後奏","短い後奏が付く（ドイツ語版Wikipedia）。"]]},"asset":"assets/impressive/heidenroslein.webp","focus":[0.5,0.48],"motion":"foliage","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"ave-verum-corpus","title":"アヴェ・ヴェルム・コルプス K.618","artist":"monet","subject":"A small modest church side altar with white linen, bread and one votive light, cool restrained daylight entering from above, simple repeated pew shapes dissolving at the edges.","rationale":"全46小節、声を抑えて歌う聖体の祈りと、半音階を経てニ長調へ戻ることから、少ない物のある聖堂を選ぶ。モネの物を光へ溶かす扱いで静けさを作る。","source":"songs/ave-verum-corpus.md","evidence":{"summary":"1791年、バーデンの教会音楽家シュトルのために書かれた全46小節の聖体モテット。合唱と弦、オルガンだけの簡素さの中に、深い祈りが宿る。","nameOrigin":"ラテン語の聖体讃歌の冒頭句「Ave verum corpus」（めでたし、まことの御体よ）から。13世紀ごろの聖体の賛歌が基になっている。","features":"全46小節という短さ、合唱・弦・オルガンだけの簡素な編成。自筆譜には曲頭にsotto voce（声を抑えて）の指示があるのみ。半音階的な和声が、死や救い、聖体拝領という宗教的な主題を表現する（Wikipediaの記述）。","structure":[["前半（導入から中間）","静かな弦の動きに乗って、合唱が聖体への賛美を和声的に歌う"],["中間部","半音階的な和声で受難と死への思いが深まる"],["結び","穏やかなニ長調に戻り、祈りの余韻で終わる"]]},"asset":"assets/impressive/ave-verum-corpus.webp","focus":[0.5,0.48],"motion":"light","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"erlkonig","title":"魔王","artist":"guillaumin","subject":"A father protecting a clothed child while riding one anatomically believable horse through a dark windy forest, distant branches only hint at a beckoning shape, violet trunks and copper ground, no gore.","rationale":"父子の夜の疾走、止まらない三連符、長調で誘う魔王という物語に基づく。ギヨマンの厚い方向性のある筆触と強い色の対立で、甘さと恐怖を同じ森に置く。","source":"songs/erlkonig.md","evidence":{"summary":"ゲーテの詩による物語歌曲。夜道を駆ける父子と魔王を、一人の歌手と疾走するピアノの三連符で描く、18歳シューベルトの出世作。","nameOrigin":"ゲーテのバラード『Erlkönig』（魔王＝Erlking、子どもを連れ去る超自然的存在）の題をそのまま用いたもの。語源の詳細は今回の資料では未確認。","features":"一人の歌手が4役（語り手・父・息子・魔王）を音域・調性・リズムで描き分ける。魔王の旋律だけが長調で、伴奏の低音三連符から一時的に解放される。半音上行の音型が悪魔的な力を象徴し、子の叫びは毎回半音ずつ高くなる。歌手にも伴奏者にも高い技巧が求められる難曲として知られる。","structure":[["序奏（1〜15小節）","ト短調。右手の三連符の連打で疾走する馬を描き、左手が不吉な上行音階と下行アルペジョの動機を示す。"],["語り手・父と子（〜57小節）","ト短調から変ロ長調へ。語り手は中音域、父は低音域、子は高音域で歌われる。"],["魔王の誘い（58〜72小節ほか）","変ロ長調の甘く媚びる旋律。伴奏の三連符は残るが音型が変わり、第2・第3の誘いでは調が上がっていく。"],["子の三度の叫び","『お父さん』の呼びかけが半音ずつ上がって繰り返され、間隔も次第に詰まる。"],["終結（132小節〜）","ト短調に戻り、三連符が止まって無伴奏のレチタティーヴォで子の死が語られる。"]]},"asset":"assets/impressive/erlkonig.webp","focus":[0.5,0.48],"motion":"foliage","medium":"painting","focusPortrait":[0.54,0.48],"protect":[0.3,0.17,0.4,0.66]},{"id":"caccini-ave-maria","title":"カッチーニのアヴェ・マリア","artist":"monet","subject":"A modest twentieth-century chapel interior with plain wooden benches, one pale blue window and a solitary small candle, no Renaissance lute, manuscript or historical composer portrait.","rationale":"実作者が20世紀のヴァヴィロフであることと、ヴォカリーズ的な長い祈りを優先する。モネの光の色面で現代にも続く祈りを描き、誤帰属を史実の絵にしない。","source":"songs/caccini-ave-maria.md","evidence":{"summary":"ソ連のリュート奏者ヴァヴィロフが1970年頃に書いたアリアで、のちにカッチーニ作として世界に広まった偽作。ヴォカリーズ的な長い旋律で、今も多くの歌手が歌う。","nameOrigin":"「カッチーニの」という通称は、ヴァヴィロフ没後に付いた誤った帰属に由来する。歌詞は典礼で広く用いられる聖母への祈り「アヴェ・マリア」の冒頭部分。","features":"和声が古い時代には存在しないもので、専門家が聴けば20世紀以降の音楽と判断できる、と日本の解説記事は述べる。また同種の曲なら3拍子が自然なのに4拍子で書かれている点も偽作とされる根拠として紹介されている。","structure":[["概要","独唱とそれを支える伴奏からなる短いアリア。版や編曲ごとに調・伴奏が異なり、楽曲内部の詳細な構成は一次資料で確認できていない。"],["編曲の系譜","オルガン版（ガランテ）、管弦楽編曲（ニック・イングマン、スティーヴン・マーキュリオ等）、器楽独奏版など多数の版がある。"]]},"asset":"assets/impressive/caccini-ave-maria.webp","focus":[0.5,0.48],"motion":"light","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"faure-pie-jesu","title":"ピエ・イェズ（フォーレ《レクイエム》作品48 第4曲）","artist":"twachtman","subject":"An almost white morning garden around a small quiet sanctuary, an empty bench, pale frost-green grass and three near-invisible ascending layers of mist, a few spare dark branches.","rationale":"恐怖より安息を前面に出す三度の呼びかけから、白い空気が少しずつ深くなる庭を選んだ。トワクトマンの抑えた銀灰色と薄い層で、救いを静かに描く。","source":"songs/faure-pie-jesu.md","evidence":{"summary":"フォーレ《レクイエム》の中心に置かれたソプラノ独唱の短い祈り。変ロ長調の簡素な旋律が三度繰り返され、安息への願いを静かに深めていく。","nameOrigin":"ラテン語の呼格「Pie Iesu」（慈悲深きイエスよ）に由来する。『怒りの日』続唱の最後の二行にあたる祈りの詩句で、レクイエムの多くの作曲家が独立楽章として扱ってきた。","features":"フォーレは伝統的な「怒りの日」続唱を全曲では置かず、この一節だけを残した。恐怖より安らぎを前面に出す全曲の性格を、中央のこの楽章が象徴する。サン＝サーンスは「モーツァルトの『アヴェ・ヴェルム・コルプス』が唯一であるように、これが唯一のピエ・イェズだ」と評したと伝わる。","structure":[["第1の呼びかけ","変ロ長調、6小節のモード的な旋律。"],["第2の呼びかけ","似た旋律がより高い音域に届く。"],["第3の呼びかけ","最初の形で始まり、より低い音域で二音を行き来しつつ、最後の「requiem」は穏やかに上行して終わる。"],["伴奏","オルガンと弦、ハープ。最終版ではフルートとクラリネットがこの楽章でのみ加わる。"]]},"asset":"assets/impressive/faure-pie-jesu.webp","focus":[0.5,0.48],"motion":"sky","medium":"painting","focusPortrait":[0.5,0.48]},{"id":"verdi-dies-irae","title":"怒りの日（ディエス・イレ）（ヴェルディ《レクイエム》第2曲の冒頭）","artist":"monet","subject":"An immense storm surf breaking against dark stone cliffs, repeated powerful diagonals of white spray under a low violet-blue sky, one central rock nearly swallowed by the swell; forceful tangible oil paint.","rationale":"最後の審判を描く合唱と大太鼓の衝撃、何度も戻る動機から、繰り返す巨大な波と暗い岩を選ぶ。モネの荒れた海を捉える筆触を強く用い、抽象的な閃光にはしない。","source":"songs/verdi-dies-irae.md","evidence":{"summary":"ヴェルディのレクイエムで最後の審判を描く合唱の爆発。大太鼓と金管が炸裂する冒頭は終曲でも再現され、映画やテレビでも多用される。","nameOrigin":"「Dies irae」はラテン語で「怒りの日」。中世の続唱の冒頭句で、最後の審判の日を指す。曲名は典礼文の冒頭に由来し、ヴェルディはこの続唱を全体の中心に据えた。","features":"オペラで培った劇的な対比と力強いリズムを宗教曲に持ち込んだ。大太鼓は通常のほか、極弱音の不気味なロール用に大型の「ヴェルディ・バスドラム」を使う指揮者もいる。教会より劇場向きという批判と、ブラームスが楽譜を見て「天才の作品」と評したという逸話が対照的である。","structure":[["冒頭","衝撃的な和音の連打、跳躍する上行句、大太鼓の裏拍の強打、木管の駆け上がり、弦のトレモロ、トランペットの細かな動きなどが重なる（D.ケアンズの解説）。"],["再現","「Quid sum miser」の前、「Lacrymosa」の前、そして終曲リベラ・メの後でも再現される（日本語版Wikipedia）。"],["続く曲","「Tuba mirum」では舞台上のトランペットに舞台裏の4本が加わり、審判のラッパを表す。"]]},"asset":"assets/impressive/verdi-dies-irae.webp","focus":[0.5,0.48],"motion":"water","medium":"painting","focusPortrait":[0.5,0.48]}]};
